// TCP Quant Terminal: one file for the Cloudflare dashboard (Edit code, paste, Deploy).
// Built by terminal/build.mjs from terminal/src; edit those files, not this one.

// Pure functions, no dependencies. Times are Unix seconds (UTC); bars are
// { t, o, h, l, c } with t the bar's open time, oldest first.
//
// These are standard, public reference levels (previous day and week, opens,
// session ranges, round numbers) and a probability engine built on a plain,
// stated model: price as a trendless random walk with each market's own
// hour-by-hour volatility. It forecasts reach, not direction, and it checks
// itself against history (calibrate). No strategy rules live here: the algo's
// own zones join the terminal only after they pass their forward test.

const MARKETS = {
  XAUUSD: { symbol: 'XAUUSD', name: 'Gold', digits: 2, contract: 100, day: 'ny', round: 50 },
  BTCUSD: { symbol: 'BTCUSD', name: 'Bitcoin', digits: 2, contract: 1, day: 'utc', round: 1000 },
};

// Forex sessions in local time, Monday to Friday.
const SESSIONS = [
  { id: 'sydney', name: 'Sydney', tz: 'Australia/Sydney', open: 7, close: 16 },
  { id: 'tokyo', name: 'Tokyo', range: 'Asia', tz: 'Asia/Tokyo', open: 9, close: 18 },
  { id: 'london', name: 'London', range: 'London', tz: 'Europe/London', open: 8, close: 17 },
  { id: 'newyork', name: 'New York', range: 'New York', tz: 'America/New_York', open: 8, close: 17 },
];

// ------------------------------------------------------------ time zones
const formatters = {};
function zoned(ts, tz) {
  formatters[tz] ||= new Intl.DateTimeFormat('en-GB', {
    timeZone: tz, hourCycle: 'h23', weekday: 'short',
    year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', second: '2-digit',
  });
  const p = {};
  for (const { type, value } of formatters[tz].formatToParts(new Date(ts * 1000))) p[type] = value;
  return { y: +p.year, m: +p.month, d: +p.day, h: +p.hour, min: +p.minute, s: +p.second, wd: p.weekday };
}

// The UTC time of a wall-clock time in a time zone (DST-aware).
function wallToUtc(tz, y, m, d, h = 0, min = 0) {
  const wall = Date.UTC(y, m - 1, d, h, min) / 1000;
  let ts = wall;
  for (let i = 0; i < 3; i++) {
    const z = zoned(ts, tz);
    const offset = Date.UTC(z.y, z.m - 1, z.d, z.h, z.min, z.s) / 1000 - ts;
    const next = wall - offset;
    if (next === ts) break;
    ts = next;
  }
  return ts;
}

// New York time without Intl, for loops over thousands of bars (a Worker on the free
// plan gets 10 ms of CPU per request). US daylight saving runs from the second Sunday
// in March, 02:00 local (07:00 UTC), to the first Sunday in November, 02:00 local (06:00 UTC).
function nthSunday(y, month, n, hourUtc) {
  const first = new Date(Date.UTC(y, month - 1, 1)).getUTCDay();
  return Date.UTC(y, month - 1, 1 + ((7 - first) % 7) + 7 * (n - 1), hourUtc) / 1000;
}
const usDst = {};
function nyOffset(ts) {
  // The year only picks the daylight-saving window, and both windows sit far from New
  // Year, so the average Gregorian year (365.2425 days) is exact enough and needs no Date.
  const y = 1970 + Math.floor(ts / 31556952);
  const [from, to] = (usDst[y] ||= [nthSunday(y, 3, 2, 7), nthSunday(y, 11, 1, 6)]);
  return ts >= from && ts < to ? -4 * 3600 : -5 * 3600;
}
const DAY = 86400;
const nyHour = (ts) => Math.floor(((((ts + nyOffset(ts)) % DAY) + DAY) % DAY) / 3600);

// A trading day as a whole number of days since 1970 (fast; dayKey gives the same day as text).
function dayIndex(ts, market) {
  if (market.day === 'utc') return Math.floor(ts / DAY);
  const i = Math.floor((ts + nyOffset(ts) + 7 * 3600) / DAY);
  const wd = (i + 4) % 7; // 1 January 1970 was a Thursday; 0 is Sunday
  return wd === 6 ? i + 2 : wd === 0 ? i + 1 : i;
}

const iso = (y, m, d) => `${y}-${String(m).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
const addDays = (key, n) => new Date(Date.parse(key + 'T00:00:00Z') + n * 86400e3).toISOString().slice(0, 10);
const weekdayOf = (key) => new Date(key + 'T00:00:00Z').getUTCDay(); // 0 Sunday ... 6 Saturday
const mondayOf = (key) => addDays(key, -((weekdayOf(key) + 6) % 7));

// The trading day a moment belongs to. Gold's day ends at 17:00 New York (as on
// broker charts), and a weekend belongs to the Monday after it; Bitcoin uses UTC days.
const keyOf = (index) => new Date(index * DAY * 1000).toISOString().slice(0, 10);
const dayKey = (ts, market) => keyOf(dayIndex(ts, market));

// ------------------------------------------------------------------- bars
// Merge bars (or days) that share a key into one bar per key.
function groupBars(bars, keyOf) {
  const out = [];
  for (const b of bars) {
    const key = keyOf(b);
    const last = out[out.length - 1];
    if (last && last.key === key) {
      last.h = Math.max(last.h, b.h);
      last.l = Math.min(last.l, b.l);
      last.c = b.c;
    } else {
      out.push({ key, t: b.t, o: b.o, h: b.h, l: b.l, c: b.c });
    }
  }
  return out;
}

function toDays(bars, market) {
  const days = [];
  let index = null;
  for (const b of bars) {
    const i = dayIndex(b.t, market);
    const last = days[days.length - 1];
    if (last && i === index) {
      last.h = Math.max(last.h, b.h);
      last.l = Math.min(last.l, b.l);
      last.c = b.c;
    } else {
      index = i;
      days.push({ key: keyOf(i), t: b.t, o: b.o, h: b.h, l: b.l, c: b.c });
    }
  }
  return days;
}

// Wilder's average true range over completed days.
function atr(days, period = 14) {
  if (days.length < period + 1) return null;
  const tr = days.slice(1).map((d, i) => Math.max(d.h - d.l, Math.abs(d.h - days[i].c), Math.abs(d.l - days[i].c)));
  let value = tr.slice(0, period).reduce((a, b) => a + b, 0) / period;
  for (const x of tr.slice(period)) value = (value * (period - 1) + x) / period;
  return value;
}

function rangeOf(bars, from, to) {
  const inside = bars.filter((b) => b.t >= from && b.t < to);
  if (!inside.length) return null;
  return { high: Math.max(...inside.map((b) => b.h)), low: Math.min(...inside.map((b) => b.l)) };
}

// Session windows on a trading day's date, in UTC.
function sessionWindow(session, key) {
  const [y, m, d] = key.split('-').map(Number);
  return { from: wallToUtc(session.tz, y, m, d, session.open), to: wallToUtc(session.tz, y, m, d, session.close) };
}

// ---------------------------------------------------------------- snapshot
// days: daily bars (the last may be today's, still forming); intraday: 15-minute bars.
function snapshot(market, days, intraday, now) {
  const today = dayKey(now, market);
  const done = days.filter((d) => d.key < today);
  let current = days.find((d) => d.key === today) || null;
  const fresh = intraday.filter((b) => dayKey(b.t, market) === today);
  if (fresh.length) {
    current = {
      key: today, t: current ? current.t : fresh[0].t, o: current ? current.o : fresh[0].o,
      h: Math.max(current ? current.h : -Infinity, ...fresh.map((b) => b.h)),
      l: Math.min(current ? current.l : Infinity, ...fresh.map((b) => b.l)),
      c: fresh[fresh.length - 1].c,
    };
  }
  const prev = done[done.length - 1] || null;
  const price = intraday.length ? intraday[intraday.length - 1].c : current ? current.c : prev ? prev.c : null;

  const thisWeek = mondayOf(today);
  const weeks = groupBars(done, (d) => mondayOf(d.key));
  const prevWeek = [...weeks].reverse().find((w) => w.key < thisWeek) || null;
  const weekOpenDay = days.find((d) => mondayOf(d.key) === thisWeek) || null;

  const averageRange = atr(done);
  const todayRange = current ? current.h - current.l : 0;

  const levels = [];
  const add = (id, name, value) => { if (Number.isFinite(value)) levels.push({ id, name, price: value }); };
  if (prev) { add('pdh', 'Previous day high', prev.h); add('pdl', 'Previous day low', prev.l); }
  if (prevWeek) { add('pwh', 'Previous week high', prevWeek.h); add('pwl', 'Previous week low', prevWeek.l); }
  if (current) add('do', 'Day open', current.o);
  if (weekOpenDay) add('wo', 'Week open', weekOpenDay.o);

  const sessions = {};
  for (const s of SESSIONS.filter((x) => x.range)) {
    const { from, to } = sessionWindow(s, today);
    const r = from <= now ? rangeOf(intraday, from, Math.min(to, now + 1)) : null;
    sessions[s.id] = r && { ...r, from, to, done: now >= to };
    if (r) { add(`${s.id}_h`, `${s.range} high`, r.high); add(`${s.id}_l`, `${s.range} low`, r.low); }
  }
  if (Number.isFinite(price)) {
    const below = Math.floor(price / market.round) * market.round;
    add('round_up', 'Round number', below + market.round);
    add('round_down', 'Round number', below === price ? below - market.round : below);
  }
  levels.sort((a, b) => b.price - a.price);

  return {
    symbol: market.symbol, name: market.name, digits: market.digits, day: today,
    price,
    dayOpen: current ? current.o : null,
    dayHigh: current ? current.h : null,
    dayLow: current ? current.l : null,
    change: current && Number.isFinite(price) ? price - current.o : null,
    changePct: current && Number.isFinite(price) ? ((price - current.o) / current.o) * 100 : null,
    atr: averageRange,
    todayRange,
    rangePct: averageRange ? (todayRange / averageRange) * 100 : null,
    levels,
    sessions,
  };
}

// ------------------------------------------------------------ session clock
// Which sessions are open at `now`, and when each next opens or closes.
function sessionClock(now) {
  return SESSIONS.map((s) => {
    const z = zoned(now, s.tz);
    const base = iso(z.y, z.m, z.d);
    let open = null;
    let next = null;
    for (let i = -1; i <= 7 && !next; i++) {
      const key = addDays(base, i);
      const wd = weekdayOf(key);
      if (wd === 0 || wd === 6) continue;
      const w = sessionWindow(s, key);
      if (w.from <= now && now < w.to) open = w;
      else if (w.from > now && !next) next = w;
    }
    return open
      ? { id: s.id, name: s.name, open: true, closesIn: open.to - now, until: open.to }
      : { id: s.id, name: s.name, open: false, opensIn: next ? next.from - now : null, at: next && next.from };
  });
}

// Gold closes from Friday 17:00 to Sunday 18:00 New York, with a daily break
// from 17:00 to 18:00; Bitcoin never closes.
function marketStatus(market, now) {
  if (market.day === 'utc') return { open: true };
  const z = zoned(now, 'America/New_York');
  const key = iso(z.y, z.m, z.d);
  const wd = weekdayOf(key);
  const hour = z.h + z.min / 60;
  const at = (dayOffset, h) => {
    const [y, m, d] = addDays(key, dayOffset).split('-').map(Number);
    return wallToUtc('America/New_York', y, m, d, h);
  };
  if (wd === 6) return { open: false, reason: 'weekend', opensAt: at(1, 18) };
  if (wd === 0 && hour < 18) return { open: false, reason: 'weekend', opensAt: at(0, 18) };
  if (wd === 5 && hour >= 17) return { open: false, reason: 'weekend', opensAt: at(2, 18) };
  if (hour >= 17 && hour < 18) return { open: false, reason: 'daily break', opensAt: at(0, 18) };
  const closeDay = hour >= 18 ? 1 : 0;
  return { open: true, closesAt: at(closeDay, 17), weekendClose: weekdayOf(addDays(key, closeDay)) === 5 };
}

// ------------------------------------------------------------------- risk
// usdPerUnit: the US-dollar value of one unit of the account currency
// (1 for USD accounts; about 1.3 for GBP). Lots round down to the broker's step.
function lotSize({ balance, riskPct, entry, stop, contract, usdPerUnit = 1, step = 0.01, min = 0.01 }) {
  const riskMoney = (balance * riskPct) / 100;
  const distance = Math.abs(entry - stop);
  const riskPerLot = (distance * contract) / usdPerUnit; // account currency lost at the stop, per 1.00 lot
  if (!(riskMoney > 0) || !(riskPerLot > 0)) return null;
  const lots = Math.floor(riskMoney / riskPerLot / step + 1e-9) * step;
  const rounded = Math.round(lots * 100) / 100;
  const side = entry > stop ? 'long' : 'short';
  const r = (k) => (side === 'long' ? entry + k * distance : entry - k * distance);
  return {
    side, riskMoney, distance, riskPerLot,
    lots: rounded,
    tooSmall: rounded < min,
    actualRisk: rounded * riskPerLot,
    perPoint: (rounded * contract) / usdPerUnit, // account currency per $1 move
    targets: [1, 2, 3].map((k) => ({ r: k, price: r(k), profit: k * rounded * riskPerLot })),
  };
}

// ------------------------------------------------------------- formatting
const fmtNum = (v, digits = 2) =>
  Number.isFinite(v) ? v.toLocaleString('en-GB', { minimumFractionDigits: digits, maximumFractionDigits: digits }) : '—';

function fmtDuration(seconds) {
  if (!Number.isFinite(seconds)) return '—';
  const m = Math.max(0, Math.round(seconds / 60));
  const d = Math.floor(m / 1440);
  const h = Math.floor((m % 1440) / 60);
  if (d) return `${d}d ${h}h`;
  return h ? `${h}h ${m % 60}m` : `${m % 60}m`;
}

// ------------------------------------------------------- probability engine
// The model: over the rest of the trading day, log price moves like a trendless
// random walk whose variance follows the market's own hour-of-day pattern (gold is
// quiet in Asia and busy at the London and New York opens). Under that model the
// reflection principle gives the chance of touching a level before the close.
// calibrate() replays history out of sample to show how honest the numbers are.

// Standard normal CDF (Abramowitz and Stegun 7.1.26, error below 1.5e-7).
function normCdf(x) {
  const z = Math.abs(x) / Math.SQRT2;
  const t = 1 / (1 + 0.3275911 * z);
  const erf = 1 - ((((1.061405429 * t - 1.453152027) * t + 1.421413741) * t - 0.284496736) * t + 0.254829592) * t * Math.exp(-z * z);
  return x >= 0 ? (1 + erf) / 2 : (1 - erf) / 2;
}

// Variance of hourly log returns for each hour of the day (New York time), from
// hourly bars. Thin hours are pulled towards the all-hours average.
function volProfile(hourly, shrink = 5) {
  const sums = new Array(24).fill(0);
  const counts = new Array(24).fill(0);
  for (let i = 1; i < hourly.length; i++) {
    const a = hourly[i - 1];
    const b = hourly[i];
    if (b.t - a.t !== 3600 || !(a.c > 0) || !(b.c > 0)) continue; // skip breaks and weekends
    const r = Math.log(b.c / a.c);
    const h = nyHour(b.t);
    sums[h] += r * r;
    counts[h] += 1;
  }
  const n = counts.reduce((a, b) => a + b, 0);
  const overall = n ? sums.reduce((a, b) => a + b, 0) / n : 0;
  return sums.map((s, h) => (s + shrink * overall) / (counts[h] + shrink));
}

// Expected variance of log price between two moments, hour by hour.
function varianceBetween(profile, from, to) {
  let v = 0;
  for (let t = from; t < to;) {
    const next = Math.min(to, (Math.floor(t / 3600) + 1) * 3600);
    v += (profile[nyHour(t)] * (next - t)) / 3600;
    t = next;
  }
  return v;
}

// When the current trading day ends: 17:00 New York for gold, midnight UTC for Bitcoin.
function dayEnd(key, market) {
  const [y, m, d] = key.split('-').map(Number);
  if (market.day === 'utc') return Date.UTC(y, m - 1, d + 1) / 1000;
  const naive = Date.UTC(y, m - 1, d, 17) / 1000;
  return naive - nyOffset(naive);
}

// Chance of touching `level` before the close, with `variance` of log price left.
function touchProb(price, level, variance) {
  if (!(price > 0) || !(level > 0)) return null;
  if (!(variance > 0)) return price === level ? 1 : 0;
  const z = Math.abs(Math.log(level / price)) / Math.sqrt(variance);
  return Math.min(1, 2 * (1 - normCdf(z)));
}

// Chance of closing beyond `level`, on its side of the price.
function beyondProb(price, level, variance) {
  if (!(variance > 0)) return 0;
  return 1 - normCdf(Math.abs(Math.log(level / price)) / Math.sqrt(variance));
}

// The band that holds the close with a given probability (k = 1: 68%, k = 2: 95%).
const band = (price, variance, k) => [price * Math.exp(-k * Math.sqrt(variance)), price * Math.exp(k * Math.sqrt(variance))];

// The widening cone from now to the close, every `step` seconds.
function cone(price, profile, from, to, step = 900) {
  const points = [];
  let v = 0;
  for (let t = from; t < to;) {
    const next = Math.min(to, (Math.floor(t / step) + 1) * step);
    v += varianceBetween(profile, t, next);
    t = next;
    const [l1, u1] = band(price, v, 1);
    const [l2, u2] = band(price, v, 2);
    points.push({ t, l1, u1, l2, u2 });
  }
  return points;
}

// Probabilities for each level that can still be reached today. Levels inside
// today's range have already been touched.
function levelOdds(levels, price, high, low, variance) {
  return levels.map((l) => {
    const touched = Number.isFinite(high) && Number.isFinite(low) && l.price <= high && l.price >= low;
    return { ...l, side: l.price >= price ? 'above' : 'below', touched,
      touch: touched ? 1 : touchProb(price, l.price, variance),
      close: beyondProb(price, l.price, variance) };
  });
}

// Descriptive state of the market from hourly bars: trend efficiency over the last
// 24 hours (0 = choppy, 1 = one-way), momentum in standard deviations over 1, 4 and
// 24 hours, and where the last 24 hours' volatility ranks against the history.
function marketState(hourly, profile) {
  const n = hourly.length;
  if (n < 50) return null;
  const closes = hourly.map((b) => b.c);
  const last = closes[n - 1];
  const window = closes.slice(-25);
  let path = 0;
  for (let i = 1; i < window.length; i++) path += Math.abs(window[i] - window[i - 1]);
  const efficiency = path ? Math.abs(window[window.length - 1] - window[0]) / path : 0;
  const hourVar = profile.reduce((a, b) => a + b, 0) / 24;
  const momentum = (h) => Math.log(last / closes[n - 1 - h]) / Math.sqrt(hourVar * h);
  const sq = [0];
  for (let i = 1; i < n; i++) sq.push(sq[i - 1] + Math.log(closes[i] / closes[i - 1]) ** 2);
  const rv = (i) => sq[i] - sq[i - 24];
  const now = rv(n - 1);
  const past = [];
  for (let i = 24; i < n - 24; i += 6) past.push(rv(i));
  const rank = past.filter((x) => x < now).length / past.length;
  return { efficiency, momentum: { h1: momentum(1), h4: momentum(4), h24: momentum(24) }, volRank: rank, vol24: Math.sqrt(now) };
}

// Out-of-sample check of the touch probabilities on the previous day's high and low.
// For each past day: a volatility profile from the `lookback` days before it only,
// then at every hourly bar a forecast for each level not yet touched, scored against
// what happened by the close.
// One pass over the bars (it runs inside the Worker's CPU budget): the profile rolls
// forward a day at a time, and the variance left to the close is a suffix sum.
function calibrate(hourly, market, lookback = 20) {
  const days = [];
  for (let i = 0; i < hourly.length; i++) {
    const b = hourly[i];
    const a = hourly[i - 1];
    const day = dayIndex(b.t, market);
    const r2 = a && b.t - a.t === 3600 && a.c > 0 && b.c > 0 ? Math.log(b.c / a.c) ** 2 : null;
    const bar = { ...b, hour: nyHour(b.t), r2 };
    const last = days[days.length - 1];
    if (last && last.day === day) last.bars.push(bar);
    else days.push({ day, bars: [bar] });
  }
  const sums = new Array(24).fill(0);
  const counts = new Array(24).fill(0);
  const tally = (bars, sign) => {
    for (const b of bars) if (b.r2 !== null) { sums[b.hour] += sign * b.r2; counts[b.hour] += sign; }
  };
  const pairs = [];
  for (let d = 0; d < days.length - 1; d++) {
    if (d > lookback) {
      const n = counts.reduce((a, b) => a + b, 0);
      const overall = n ? sums.reduce((a, b) => a + b, 0) / n : 0;
      const profile = sums.map((s, h) => (s + 5 * overall) / (counts[h] + 5));
      const prev = days[d - 1].bars;
      let pdh = -Infinity;
      let pdl = Infinity;
      for (const b of prev) { pdh = Math.max(pdh, b.h); pdl = Math.min(pdl, b.l); }
      const bars = days[d].bars;
      const k = bars.length;
      const highAfter = new Array(k);
      const lowAfter = new Array(k);
      const varAfter = new Array(k);
      for (let i = k - 1; i >= 0; i--) {
        highAfter[i] = Math.max(bars[i].h, i + 1 < k ? highAfter[i + 1] : -Infinity);
        lowAfter[i] = Math.min(bars[i].l, i + 1 < k ? lowAfter[i + 1] : Infinity);
        varAfter[i] = profile[bars[i].hour] + (i + 1 < k ? varAfter[i + 1] : 0);
      }
      let high = -Infinity;
      let low = Infinity;
      for (let i = 0; i < k; i++) {
        const price = bars[i].o;
        if (high < pdh && price < pdh) pairs.push([touchProb(price, pdh, varAfter[i]), highAfter[i] >= pdh ? 1 : 0]);
        if (low > pdl && price > pdl) pairs.push([touchProb(price, pdl, varAfter[i]), lowAfter[i] <= pdl ? 1 : 0]);
        high = Math.max(high, bars[i].h);
        low = Math.min(low, bars[i].l);
      }
    }
    // Roll the profile's window forward: this day in, the day `lookback` back out.
    tally(days[d].bars, 1);
    if (d - lookback >= 0) tally(days[d - lookback].bars, -1);
  }
  if (pairs.length < 50) return null;
  const rate = pairs.reduce((a, [, o]) => a + o, 0) / pairs.length;
  const brier = pairs.reduce((a, [p, o]) => a + (p - o) ** 2, 0) / pairs.length;
  const reference = rate * (1 - rate); // always forecasting the average rate
  const bins = [];
  for (let k = 0; k < 5; k++) {
    const lo = k / 5;
    const hi = (k + 1) / 5;
    const inside = pairs.filter(([p]) => p >= lo && (k === 4 ? p <= hi : p < hi));
    if (!inside.length) continue;
    bins.push({ lo, hi, n: inside.length,
      predicted: inside.reduce((a, [p]) => a + p, 0) / inside.length,
      observed: inside.reduce((a, [, o]) => a + o, 0) / inside.length });
  }
  return { days: days.length - 2 - lookback, n: pairs.length, brier, skill: reference ? 1 - brier / reference : 0, bins };
}

// Baseline odds for a trade on a trendless market: the chance the target comes
// before the stop, and the typical time until one of them is hit.
function tradeOdds(entry, stop, target, hourVar) {
  const risk = Math.abs(entry - stop);
  const reward = Math.abs(target - entry);
  if (!(risk > 0) || !(reward > 0)) return null;
  const sigma2 = hourVar * entry * entry; // price variance per hour
  return { targetFirst: risk / (risk + reward), hours: sigma2 > 0 ? (risk * reward) / sigma2 : null };
}

const PAGE = "<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\">\n<title>TCP Quant Terminal</title>\n<meta name=\"color-scheme\" content=\"dark\">\n<script src=\"https://telegram.org/js/telegram-web-app.js\"></script>\n<script src=\"https://cdn.jsdelivr.net/npm/lightweight-charts@4.2.3/dist/lightweight-charts.standalone.production.js\" integrity=\"sha384-stKllnUqA9AD0gsKCuUtf5XlqAW7PwIgDagoNsTWkjkBmJ/GZ/uHTgEBxdLV2VSK\" crossorigin=\"anonymous\"></script>\n<style>\n@font-face{font-family:\"Archivo\";src:url(/fonts/archivo-400.woff2) format(\"woff2\");font-weight:400;font-display:swap}\n@font-face{font-family:\"TCP Display\";src:url(/fonts/archivo-expanded-800.woff2) format(\"woff2\");font-weight:800;font-display:swap}\n@font-face{font-family:\"JetBrains Mono\";src:url(/fonts/jetbrains-mono-500.woff2) format(\"woff2\");font-weight:500;font-display:swap}\n@font-face{font-family:\"JetBrains Mono\";src:url(/fonts/jetbrains-mono-600.woff2) format(\"woff2\");font-weight:600;font-display:swap}\n@font-face{font-family:\"Instrument Serif\";src:url(/fonts/instrument-serif-italic.woff2) format(\"woff2\");font-style:italic;font-display:swap}\n:root{\n  --ink:#0E0D0B;--panel:#16140F;--panel-2:#1C1A15;--line:#2E2A22;--line-2:#3A3429;\n  --gold:#D8AD4E;--gold-soft:#E3C06D;--ivory:#F2ECDF;--stone:#A69D8C;--muted:#8A8274;\n  --royal:#8C7BD1;--up:#35A68C;--down:#E0613F;\n  --display:\"TCP Display\",\"Archivo\",system-ui,sans-serif;--sans:\"Archivo\",system-ui,-apple-system,sans-serif;\n  --mono:\"JetBrains Mono\",ui-monospace,monospace;--serif:\"Instrument Serif\",Georgia,serif;\n  --foil:linear-gradient(180deg,#F6E3A3 0%,#D8AD4E 42%,#B0812F 72%,#E3C06D 100%);\n  --foil-x:linear-gradient(90deg,#B0812F 0%,#D8AD4E 45%,#F6E3A3 100%);\n}\n*{box-sizing:border-box}\nhtml,body{margin:0;background:var(--ink);color:var(--ivory)}\nbody{font:400 15px/1.45 var(--sans);min-height:100vh;-webkit-font-smoothing:antialiased;\n  background:radial-gradient(120% 50% at 50% -12%,rgba(216,173,78,.13),transparent 62%),var(--ink);\n  padding-bottom:calc(76px + env(safe-area-inset-bottom))}\nbutton,input,select{font:inherit;color:inherit}\n[hidden]{display:none!important}\n.label{font:500 10.5px/1 var(--mono);letter-spacing:.2em;text-transform:uppercase;color:var(--stone);white-space:nowrap}\n\nheader{display:flex;align-items:center;gap:10px;padding:14px 16px 6px}\nheader svg{width:30px;height:auto;flex:none}\n.brand{display:flex;flex-direction:column;gap:3px}\n.brand b{font:800 17px/1 var(--display);letter-spacing:.02em}\n.brand span{font:600 9.5px/1 var(--mono);letter-spacing:.26em;color:var(--gold)}\n.who{margin-left:auto;display:flex;align-items:center;gap:8px;font-size:13px;color:var(--stone)}\n.avatar{width:30px;height:30px;border-radius:50%;display:grid;place-items:center;background:var(--panel-2);\n  border:1px solid var(--line-2);font:600 12px/1 var(--mono);color:var(--gold)}\n\n/* ---------------------------------------------------------- engine strip */\n.engine{position:relative;overflow:hidden;display:flex;align-items:center;gap:9px;margin:8px 16px 0;padding:9px 12px;\n  border:1px solid var(--line);border-radius:12px;background:linear-gradient(90deg,rgba(216,173,78,.07),rgba(22,20,15,.6));\n  font:600 10.5px/1 var(--mono);letter-spacing:.16em;color:var(--stone)}\n.engine::after{content:\"\";position:absolute;inset:0;background:linear-gradient(100deg,transparent 30%,rgba(246,227,163,.10) 50%,transparent 70%);\n  transform:translateX(-100%);animation:sweep 3.6s ease-in-out infinite}\n.engine b{color:var(--ivory);font-weight:600}\n.engine .sync{margin-left:auto;letter-spacing:.06em;font-weight:500;color:var(--muted);white-space:nowrap}\n.pulse{width:8px;height:8px;border-radius:50%;background:var(--up);flex:none;box-shadow:0 0 0 0 rgba(53,166,140,.6);animation:pulse 1.8s ease-out infinite}\n.engine.closed .pulse,.engine.delayed .pulse{background:var(--gold);animation:none;box-shadow:none}\n.engine.closed .eq i,.engine.delayed .eq i{animation-play-state:paused}\n.eq{display:inline-flex;align-items:flex-end;gap:2px;height:12px}\n.eq i{width:3px;height:100%;border-radius:1px;background:var(--gold);transform-origin:bottom;animation:eq 1.2s ease-in-out infinite}\n.eq i:nth-child(2){animation-delay:-.3s}.eq i:nth-child(3){animation-delay:-.6s}.eq i:nth-child(4){animation-delay:-.9s}\n@keyframes sweep{to{transform:translateX(100%)}}\n@keyframes pulse{0%{box-shadow:0 0 0 0 rgba(53,166,140,.55)}80%,100%{box-shadow:0 0 0 9px rgba(53,166,140,0)}}\n@keyframes eq{0%,100%{transform:scaleY(.25)}50%{transform:scaleY(1)}}\n\n.card{background:var(--panel);border:1px solid var(--line);border-radius:18px;padding:16px;margin:12px 16px}\n.card h2{margin:0 0 12px}\n.card > .row:first-child{margin-bottom:12px}\n.card .row h2{margin:0}\n.row{display:flex;align-items:center;gap:10px}\n.spread{justify-content:space-between}\n.meta{font-size:12px;color:var(--muted);margin-top:10px}\n.warn{color:var(--gold-soft)}\n.up{color:var(--up)}.down{color:var(--down)}\n\n.segment{display:flex;gap:8px;margin:10px 16px 0}\n.segment button{flex:1;display:flex;flex-direction:column;align-items:flex-start;gap:4px;padding:10px 14px;border-radius:14px;\n  background:var(--panel);border:1px solid var(--line);cursor:pointer;text-align:left}\n.segment button b{font:600 14px/1 var(--mono);letter-spacing:.04em}\n.segment button span{font-size:12px;color:var(--stone)}\n.segment button[aria-pressed=\"true\"]{border-color:var(--gold);background:var(--panel-2)}\n.segment button[aria-pressed=\"true\"] b{color:var(--gold)}\n\n.pill{display:inline-flex;align-items:center;gap:6px;padding:5px 10px;border-radius:999px;border:1px solid var(--line-2);\n  font:500 11.5px/1 var(--mono);color:var(--stone);white-space:nowrap}\n.dot{width:7px;height:7px;border-radius:50%;background:var(--muted)}\n.pill.open .dot{background:var(--up);box-shadow:0 0 0 3px rgba(53,166,140,.18)}\n.pill.open{color:var(--ivory)}\n\n/* ----------------------------------------------------------------- quote */\n.quote{display:grid;grid-template-columns:1fr 112px;gap:8px;align-items:end}\n.price{font:600 36px/1.05 var(--mono);letter-spacing:-.02em;margin:10px 0 6px;border-radius:8px;padding:0 4px;margin-left:-4px;transition:color .5s}\n.price.tick-up{animation:up .7s ease-out}\n.price.tick-down{animation:down .7s ease-out}\n@keyframes up{0%{background:rgba(53,166,140,.28);color:#7FE0C4}100%{background:transparent}}\n@keyframes down{0%{background:rgba(224,97,63,.28);color:#FFB39E}100%{background:transparent}}\n.change{font:500 13.5px/1.2 var(--mono)}\n#spark{width:112px;height:46px;overflow:visible}\n\n/* ----------------------------------------------------------------- chart */\n#chart{height:300px;margin:0 -6px;position:relative}\n.chart-note{position:absolute;inset:0;display:grid;place-items:center;color:var(--muted);font-size:13px;text-align:center;padding:20px}\n.keys{display:flex;flex-wrap:wrap;gap:6px 12px;margin-top:10px;font:500 10.5px/1 var(--mono);color:var(--stone)}\n.keys i{display:inline-block;width:14px;height:0;border-top:2px dashed;vertical-align:middle;margin-right:5px}\n.timer{font:600 11px/1 var(--mono);color:var(--gold-soft);letter-spacing:.06em}\n\n/* ----------------------------------------------------------- probability */\n.bands{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:14px}\n.band{padding:10px 12px;border-radius:12px;background:var(--panel-2);border:1px solid var(--line)}\n.band span{display:block;font:500 10px/1 var(--mono);letter-spacing:.16em;color:var(--stone);margin-bottom:7px}\n.band b{display:block;font:600 13.5px/1.5 var(--mono)}\n.band b small{font:500 10px/1 var(--mono);color:var(--muted);margin-right:6px}\n.touched{display:flex;flex-wrap:wrap;gap:6px;margin-top:12px;padding-top:12px;border-top:1px solid var(--line)}\n.touched .label{width:100%;margin-bottom:2px}\n.touched span:not(.label){padding:4px 9px;border-radius:999px;border:1px solid var(--line-2);font:500 11px/1.2 var(--mono);color:var(--stone)}\n.closed-note{margin:10px 0 2px;font-size:12.5px;color:var(--gold-soft)}\n.lv{padding:10px 0;border-bottom:1px solid var(--line)}\n.lv:last-child{border-bottom:0}\n.lv-top{display:grid;grid-template-columns:1fr auto 70px;gap:10px;align-items:baseline}\n.lv-name{font-size:13.5px}\n.lv-price{font:600 13.5px/1 var(--mono)}\n.lv-dist{font:500 12px/1 var(--mono);font-style:normal;color:var(--muted);text-align:right}\n.lv-odds{display:grid;grid-template-columns:1fr 44px;gap:10px;align-items:center;margin-top:8px}\n.lv-bar{height:6px;border-radius:999px;background:var(--panel-2);overflow:hidden}\n.lv-bar i{display:block;height:100%;width:0;border-radius:999px;background:var(--foil-x);transition:width .8s cubic-bezier(.2,.8,.2,1)}\n.lv.below .lv-bar i{background:linear-gradient(90deg,#6C5BB8,#8C7BD1,#B7AAF0)}\n.lv-pct{font:600 13px/1 var(--mono);text-align:right;color:var(--gold-soft)}\n.lv.below .lv-pct{color:#B7AAF0}\n.hit{display:inline-block;margin-top:8px;padding:3px 8px;border-radius:999px;border:1px solid var(--line-2);font:500 10.5px/1.2 var(--mono);color:var(--muted);letter-spacing:.06em}\n.lv.now{border:1px solid rgba(216,173,78,.5);border-radius:12px;padding:10px 12px;margin:6px -8px;background:rgba(216,173,78,.07);\n  display:flex;justify-content:space-between;align-items:center}\n.lv.now span{font-size:13.5px;color:var(--gold)}\n.lv.now b{font:600 14px/1 var(--mono);color:var(--gold)}\n.fine{font-size:12px;color:var(--muted);margin-top:12px;line-height:1.5}\n\n/* ----------------------------------------------------------------- gauges */\n.gauge{position:relative;height:10px;border-radius:999px;background:var(--panel-2);border:1px solid var(--line);margin:14px 0 8px}\n.gauge .fill{position:absolute;inset:0 auto 0 0;border-radius:999px;background:var(--foil);transition:width .8s cubic-bezier(.2,.8,.2,1)}\n.gauge .avg{position:absolute;top:-5px;bottom:-5px;width:2px;background:var(--ivory);opacity:.7}\n.gauge-scale{position:relative;height:12px;font:500 10px/1 var(--mono);color:var(--muted)}\n.gauge-scale span{position:absolute;top:0}\n.gauge-scale span:nth-child(2){left:66.6%;transform:translateX(-50%)}\n.gauge-scale span:last-child{right:0}\n.big{font:600 26px/1.1 var(--mono)}\n.sub{color:var(--stone);font-size:13.5px}\n.meter{margin-bottom:16px}\n.meter:last-child{margin-bottom:0}\n.meter .row{justify-content:space-between;align-items:baseline}\n.meter b{font:600 14px/1 var(--mono)}\n.meter small{font-size:12.5px;color:var(--stone)}\n.track{position:relative;height:8px;border-radius:999px;background:var(--panel-2);border:1px solid var(--line);margin-top:9px;overflow:hidden}\n.track i{position:absolute;top:0;bottom:0;left:0;border-radius:999px;background:var(--foil-x);transition:width .8s cubic-bezier(.2,.8,.2,1),left .8s cubic-bezier(.2,.8,.2,1)}\n.track.mid::before{content:\"\";position:absolute;left:50%;top:-2px;bottom:-2px;width:1px;background:var(--line-2);z-index:1}\n.mom{display:grid;grid-template-columns:34px 1fr 58px;gap:10px;align-items:center;margin-top:8px}\n.mom span{font:500 11px/1 var(--mono);color:var(--stone)}\n.mom em{font:600 12px/1 var(--mono);font-style:normal;text-align:right}\n.mom .track{margin-top:0}\n.mom .track i.pos{background:linear-gradient(90deg,rgba(53,166,140,.5),#35A68C)}\n.mom .track i.neg{background:linear-gradient(90deg,#E0613F,rgba(224,97,63,.5))}\n.tag{font:500 10.5px/1 var(--mono);letter-spacing:.1em;color:var(--muted);border:1px solid var(--line-2);border-radius:999px;padding:4px 8px}\n\n/* --------------------------------------------------------------- sessions */\n.sessions{display:grid;gap:8px}\n.session{position:relative;overflow:hidden;display:grid;grid-template-columns:44px 1fr auto;align-items:center;gap:10px;padding:10px 12px;border-radius:12px;background:var(--panel-2);border:1px solid var(--line)}\n.session .code{font:600 11px/1 var(--mono);letter-spacing:.12em;color:var(--stone)}\n.session.open{border-color:rgba(53,166,140,.45)}\n.session.open .code{color:var(--up)}\n.session b{font-weight:600;font-size:14px}\n.session small{display:block;color:var(--stone);font-size:12px;margin-top:2px;font-variant-numeric:tabular-nums}\n.session time{font:500 12px/1 var(--mono);color:var(--muted)}\n.session .prog{position:absolute;left:0;bottom:0;height:2px;background:linear-gradient(90deg,rgba(53,166,140,.2),#35A68C);transition:width 1s linear}\n.overlap{margin-top:10px;font-size:12.5px;color:var(--gold-soft)}\n\n/* ------------------------------------------------------------ model check */\n#checkChart{width:100%;height:auto;display:block;margin:4px 0 6px}\n.check-stats{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-top:10px}\n.check-stats div{padding:10px;border-radius:12px;background:var(--panel-2);border:1px solid var(--line);text-align:center}\n.check-stats b{display:block;font:600 16px/1.1 var(--mono);color:var(--gold-soft)}\n.check-stats span{font-size:11px;color:var(--stone)}\n\n/* -------------------------------------------------------------------- risk */\n.field{display:grid;gap:6px;margin-bottom:14px}\n.field label{font:500 10.5px/1 var(--mono);letter-spacing:.18em;text-transform:uppercase;color:var(--stone)}\n.inputs{display:flex;gap:8px}\ninput,select{width:100%;min-width:0;background:var(--panel-2);border:1px solid var(--line-2);border-radius:12px;padding:12px 12px;\n  font:500 16px/1.2 var(--mono);outline:none}\nselect{appearance:none;-webkit-appearance:none;width:auto;min-width:96px;flex:none;padding-right:34px;background-image:linear-gradient(45deg,transparent 50%,var(--stone) 50%),linear-gradient(135deg,var(--stone) 50%,transparent 50%);\n  background-position:calc(100% - 15px) 55%,calc(100% - 10px) 55%;background-size:5px 5px;background-repeat:no-repeat}\ninput:focus,select:focus{border-color:var(--gold)}\n.chips{display:flex;gap:6px}\n.chips button{padding:8px 12px;border-radius:999px;border:1px solid var(--line-2);background:transparent;font:500 13px/1 var(--mono);cursor:pointer}\n.chips button[aria-pressed=\"true\"]{border-color:var(--gold);color:var(--gold)}\n.hint{font-size:12px;color:var(--muted)}\n.link{background:none;border:0;padding:0;color:var(--gold);font-size:12.5px;cursor:pointer}\n.result{text-align:center;padding:22px 16px}\n.lots{font:800 46px/1 var(--display);background:var(--foil);-webkit-background-clip:text;background-clip:text;color:transparent;margin:8px 0 4px}\n.facts{display:grid;gap:8px;margin-top:16px;text-align:left}\n.facts div{display:flex;justify-content:space-between;gap:10px;font-size:13.5px;color:var(--stone)}\n.facts b{font:600 13.5px/1.3 var(--mono);color:var(--ivory)}\n#targets{width:100%;border-collapse:collapse;margin-top:14px;font:500 13px/1 var(--mono)}\n#targets th{font:500 10px/1 var(--mono);letter-spacing:.16em;color:var(--muted);text-align:left;padding:0 0 8px}\n#targets td{padding:9px 0;border-top:1px solid var(--line);text-align:left}\n#targets td:last-child,#targets th:last-child{text-align:right}\n.odds-note{margin-top:14px;text-align:left;font-size:12.5px;color:var(--stone);line-height:1.5}\n.odds-note b{color:var(--gold-soft);font-family:var(--mono);font-weight:600}\n.note{font-size:12px;color:var(--muted);margin:14px 16px 0;text-align:center}\n\n.soon h2{font:800 20px/1.15 var(--display);margin:6px 0 8px}\n.soon p{color:var(--stone);margin:0 0 12px}\n.soon ul{margin:0;padding:0;list-style:none;display:grid;gap:8px}\n.soon li{display:flex;gap:10px;align-items:baseline;font-size:14px}\n.soon li:before{content:\"\";width:6px;height:6px;border-radius:2px;background:var(--gold);transform:translateY(-2px);flex:none}\n.serif{font:italic 400 19px/1.2 var(--serif);color:var(--gold-soft)}\n\nnav{position:fixed;left:0;right:0;bottom:0;display:grid;grid-template-columns:repeat(4,1fr);padding:8px 8px calc(8px + env(safe-area-inset-bottom));\n  background:rgba(14,13,11,.92);backdrop-filter:blur(12px);-webkit-backdrop-filter:blur(12px);border-top:1px solid var(--line);z-index:4}\nnav button{display:grid;justify-items:center;gap:4px;padding:6px 0;background:none;border:0;color:var(--muted);font:500 10.5px/1 var(--mono);letter-spacing:.08em;cursor:pointer}\nnav svg{width:22px;height:22px}\nnav button[aria-current=\"page\"]{color:var(--gold)}\n\n.gate{position:fixed;inset:0;display:grid;place-items:center;padding:32px;text-align:center;background:var(--ink);z-index:5}\n.gate svg{width:64px;margin-bottom:18px}\n.gate h1{font:800 22px/1.15 var(--display);margin:0 0 10px}\n.gate p{color:var(--stone);margin:0 0 20px}\n.cta{display:inline-block;padding:13px 20px;border-radius:14px;background:var(--foil);color:var(--ink);font:600 14px/1 var(--mono);letter-spacing:.06em;text-decoration:none;border:0;cursor:pointer}\n.skeleton{border-radius:8px;background:linear-gradient(90deg,var(--panel-2),#24211A,var(--panel-2));background-size:200% 100%;animation:shimmer 1.4s infinite}\n@keyframes shimmer{to{background-position:-200% 0}}\n@media (prefers-reduced-motion:reduce){*,*::before,*::after{animation:none!important;transition:none!important}}\n</style>\n</head>\n<body>\n<template id=\"crown\"><svg viewBox=\"-19.2 -19.53 238.4 194.2\" aria-hidden=\"true\"><defs><linearGradient id=\"foil\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\"><stop offset=\"0\" stop-color=\"#F6E3A3\"/><stop offset=\"0.42\" stop-color=\"#D8AD4E\"/><stop offset=\"0.72\" stop-color=\"#B0812F\"/><stop offset=\"1\" stop-color=\"#E3C06D\"/></linearGradient></defs><path fill=\"url(#foil)\" fill-rule=\"evenodd\" d=\"M16 130L0 36.67L60 76.67L100 10L140 76.67L200 36.67L184 130ZM16 141.67H184V166.67H16ZM40 73.33H46V85H53V116.67H46V123.33H40V116.67H33V85H40ZM97 40H103V55H110V110H103V123.33H97V110H90V55H97ZM154 73.33H160V85H167V116.67H160V123.33H154V116.67H147V85H154Z\"/><circle cx=\"0\" cy=\"28.33\" r=\"11.2\" fill=\"url(#foil)\"/><circle cx=\"100\" cy=\"1.67\" r=\"13.2\" fill=\"url(#foil)\"/><circle cx=\"200\" cy=\"28.33\" r=\"11.2\" fill=\"url(#foil)\"/></svg></template>\n\n<header>\n  <span data-crown></span>\n  <div class=\"brand\"><b>TCP</b><span>QUANT TERMINAL</span></div>\n  <div class=\"who\" id=\"who\" hidden><span id=\"whoName\"></span><span class=\"avatar\" id=\"whoInitial\"></span></div>\n</header>\n\n<div class=\"engine\" id=\"engine\" aria-live=\"off\">\n  <span class=\"pulse\"></span><b id=\"engineState\">LIVE</b>\n  <span class=\"eq\" aria-hidden=\"true\"><i></i><i></i><i></i><i></i></span>\n  <span>QUANT ENGINE</span>\n  <span class=\"sync\" id=\"engineSync\">starting…</span>\n</div>\n\n<main>\n  <!-- ============================================================ Markets -->\n  <section id=\"markets\">\n    <div class=\"segment\" role=\"group\" aria-label=\"Market\">\n      <button data-symbol=\"XAUUSD\" aria-pressed=\"true\"><b>XAUUSD</b><span>Gold</span></button>\n      <button data-symbol=\"BTCUSD\" aria-pressed=\"false\"><b>BTCUSD</b><span>Bitcoin</span></button>\n    </div>\n\n    <div class=\"card\">\n      <div class=\"row spread\"><span class=\"label\" id=\"quoteName\">Gold · spot</span><span class=\"pill\" id=\"status\"><span class=\"dot\"></span><span></span></span></div>\n      <div class=\"quote\">\n        <div>\n          <div class=\"price\" id=\"price\"><span class=\"skeleton\" style=\"display:inline-block;width:180px;height:34px\"></span></div>\n          <div class=\"change\" id=\"change\">&nbsp;</div>\n        </div>\n        <svg id=\"spark\" viewBox=\"0 0 112 46\" preserveAspectRatio=\"none\" aria-label=\"Last 48 hours\"></svg>\n      </div>\n      <div class=\"meta\" id=\"updated\">&nbsp;</div>\n    </div>\n\n    <div class=\"card\">\n      <div class=\"row spread\"><h2 class=\"label\">Chart · 15 min</h2><span class=\"timer\" id=\"candleTimer\"></span></div>\n      <div id=\"chart\"><div class=\"chart-note\" id=\"chartNote\">Loading the chart…</div></div>\n      <div class=\"keys\">\n        <span><i style=\"color:var(--gold)\"></i>Previous day</span>\n        <span><i style=\"color:var(--gold-soft);border-top-style:solid\"></i>Previous week</span>\n        <span><i style=\"color:#8C7BD1\"></i>Asia range</span>\n        <span><i style=\"color:rgba(227,192,109,.9)\"></i>68% cone</span>\n        <span><i style=\"color:rgba(166,157,140,.8);border-top-style:dotted\"></i>95% cone</span>\n      </div>\n    </div>\n\n    <div class=\"card\">\n      <div class=\"row spread\"><h2 class=\"label\">Probability engine</h2><span class=\"tag\" id=\"closeIn\">to the close</span></div>\n      <div class=\"bands\">\n        <div class=\"band\"><span>68% CLOSE RANGE</span><b id=\"band68\">—</b></div>\n        <div class=\"band\"><span>95% CLOSE RANGE</span><b id=\"band95\">—</b></div>\n      </div>\n      <div class=\"row spread\" style=\"margin-bottom:2px\"><span class=\"label\">Level · chance of a touch</span><span class=\"label\">distance</span></div>\n      <div id=\"levels\"><div class=\"skeleton\" style=\"height:160px;margin-top:10px\"></div></div>\n      <div class=\"fine\">Chances of a touch before today's close, if price moves at random with this market's usual volatility for each hour. They measure reach, not direction. They move with every tick and shrink as the close gets nearer.</div>\n    </div>\n\n    <div class=\"card\">\n      <div class=\"row spread\"><h2 class=\"label\">Market state</h2><span class=\"tag\">not a signal</span></div>\n      <div id=\"state\"></div>\n    </div>\n\n    <div class=\"card\">\n      <h2 class=\"label\">Volatility today</h2>\n      <div class=\"row spread\" style=\"align-items:flex-end\">\n        <div><div class=\"big\" id=\"range\">—</div><div class=\"sub\">moved today</div></div>\n        <div style=\"text-align:right\"><div class=\"big\" id=\"rangePct\">—</div><div class=\"sub\">of an average day</div></div>\n      </div>\n      <div class=\"gauge\" aria-hidden=\"true\"><div class=\"fill\" id=\"gaugeFill\" style=\"width:0\"></div><div class=\"avg\" style=\"left:66.6%\"></div></div>\n      <div class=\"gauge-scale\"><span>0%</span><span>100%</span><span>150%</span></div>\n      <div class=\"meta\" id=\"atrLine\">&nbsp;</div>\n    </div>\n\n    <div class=\"card\">\n      <div class=\"row spread\"><h2 class=\"label\">Sessions</h2><span class=\"label\" id=\"localTime\"></span></div>\n      <div class=\"sessions\" id=\"sessions\"></div>\n      <div class=\"overlap\" id=\"overlap\" hidden></div>\n    </div>\n\n    <div class=\"card\">\n      <div class=\"row spread\"><h2 class=\"label\">Model check</h2><span class=\"tag\">out of sample</span></div>\n      <div id=\"check\"></div>\n    </div>\n  </section>\n\n  <!-- ============================================================== Risk -->\n  <section id=\"risk\" hidden>\n    <div class=\"card\">\n      <h2 class=\"label\">Position size</h2>\n      <div class=\"field\">\n        <label for=\"balance\">Account balance</label>\n        <div class=\"inputs\"><input id=\"balance\" inputmode=\"decimal\" placeholder=\"10000\" autocomplete=\"off\"><select id=\"currency\" aria-label=\"Account currency\"><option>USD</option><option>GBP</option><option>EUR</option></select></div>\n        <div class=\"hint\" id=\"fxHint\" hidden></div>\n      </div>\n      <div class=\"field\">\n        <label for=\"riskPct\">Risk per trade (%)</label>\n        <div class=\"inputs\"><input id=\"riskPct\" inputmode=\"decimal\" value=\"1\" autocomplete=\"off\">\n          <div class=\"chips\" id=\"riskChips\"><button data-risk=\"0.5\">0.5</button><button data-risk=\"1\">1</button><button data-risk=\"2\">2</button></div></div>\n      </div>\n      <div class=\"field\">\n        <label>Market</label>\n        <div class=\"chips\" id=\"riskMarket\"><button data-symbol=\"XAUUSD\">XAUUSD</button><button data-symbol=\"BTCUSD\">BTCUSD</button></div>\n      </div>\n      <div class=\"field\">\n        <div class=\"row spread\"><label for=\"entry\">Entry</label><button class=\"link\" id=\"useLive\" type=\"button\">Use live price</button></div>\n        <input id=\"entry\" inputmode=\"decimal\" autocomplete=\"off\">\n      </div>\n      <div class=\"field\">\n        <label for=\"stop\">Stop loss</label>\n        <input id=\"stop\" inputmode=\"decimal\" autocomplete=\"off\" placeholder=\"Your stop price\">\n      </div>\n      <div class=\"field\" style=\"margin-bottom:0\">\n        <label for=\"contract\">Contract size (per 1.00 lot)</label>\n        <input id=\"contract\" inputmode=\"decimal\" autocomplete=\"off\">\n        <div class=\"hint\">Gold is usually 100 oz and Bitcoin 1 BTC. Check yours in MT5: tap the symbol, then Specification.</div>\n      </div>\n    </div>\n\n    <div class=\"card result\" id=\"result\">\n      <div class=\"label\">Lot size</div>\n      <div class=\"lots\" id=\"lots\">—</div>\n      <div class=\"sub\" id=\"lotsLine\">Enter your balance and stop loss.</div>\n      <div class=\"facts\" id=\"facts\" hidden></div>\n      <table id=\"targets\" hidden><thead><tr><th>TARGET</th><th>PRICE</th><th>ODDS</th><th>PROFIT</th></tr></thead><tbody></tbody></table>\n      <div class=\"odds-note\" id=\"oddsNote\" hidden></div>\n    </div>\n    <p class=\"note\">A calculator, not advice. Check the numbers in MT5 before you place a trade.</p>\n  </section>\n\n  <!-- =========================================================== Signals -->\n  <section id=\"signals\" hidden>\n    <div class=\"card soon\">\n      <span class=\"pill\"><span class=\"dot\" style=\"background:var(--gold)\"></span>In testing</span>\n      <h2>Algo signals</h2>\n      <p>The TCP algorithm is in its forward test. Once it passes, its entries, exits and zones appear here and in the Inner Circle, each with its tested win rate, and every result posted in full.</p>\n      <ul><li>Entry, stop and targets, sized for your account</li><li>Live updates as trades move</li><li>A running record of every signal, wins and losses</li></ul>\n    </div>\n    <p class=\"note serif\">Proven first. Then live.</p>\n  </section>\n\n  <!-- ========================================================= My stats -->\n  <section id=\"stats\" hidden>\n    <div class=\"card soon\">\n      <span class=\"pill\"><span class=\"dot\" style=\"background:var(--gold)\"></span>Coming next</span>\n      <h2>Your trading, measured</h2>\n      <p>Connect your MT5 account to see how you really trade, and get a plain-English AI report on what to keep and what to cut.</p>\n      <ul><li>Profit factor, win rate and average R</li><li>Drawdown and your equity curve</li><li>Your best and worst sessions, days and markets</li><li>Weekly AI reports on your trading</li></ul>\n    </div>\n  </section>\n</main>\n\n<nav aria-label=\"Terminal\">\n  <button data-tab=\"markets\" aria-current=\"page\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\"><path d=\"M6 3v4M6 17v4M12 6v3M12 17v3M18 4v3M18 14v6\"/><rect x=\"4\" y=\"7\" width=\"4\" height=\"10\" rx=\"1\"/><rect x=\"10\" y=\"9\" width=\"4\" height=\"8\" rx=\"1\"/><rect x=\"16\" y=\"7\" width=\"4\" height=\"7\" rx=\"1\"/></svg>MARKETS</button>\n  <button data-tab=\"risk\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\"><circle cx=\"12\" cy=\"12\" r=\"8.5\"/><circle cx=\"12\" cy=\"12\" r=\"4.5\"/><path d=\"M12 2v4M12 18v4M2 12h4M18 12h4\"/></svg>RISK</button>\n  <button data-tab=\"signals\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linejoin=\"round\"><path d=\"M13 2 4 14h7l-1 8 9-12h-7l1-8Z\"/></svg>SIGNALS</button>\n  <button data-tab=\"stats\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\"><path d=\"M4 20h16M7 16v-4M12 16V8M17 16v-7\"/></svg>MY STATS</button>\n</nav>\n\n<div class=\"gate\" id=\"gate\">\n  <div>\n    <span data-crown></span>\n    <h1 id=\"gateTitle\">Checking your membership…</h1>\n    <p id=\"gateText\">One moment.</p>\n    <a class=\"cta\" id=\"gateCta\" hidden></a>\n  </div>\n</div>\n\n<script type=\"module\">\n// TCP Quant Terminal: the market maths, shared by the Worker and the page.\n// Pure functions, no dependencies. Times are Unix seconds (UTC); bars are\n// { t, o, h, l, c } with t the bar's open time, oldest first.\n//\n// These are standard, public reference levels (previous day and week, opens,\n// session ranges, round numbers) and a probability engine built on a plain,\n// stated model: price as a trendless random walk with each market's own\n// hour-by-hour volatility. It forecasts reach, not direction, and it checks\n// itself against history (calibrate). No strategy rules live here: the algo's\n// own zones join the terminal only after they pass their forward test.\n\nconst MARKETS = {\n  XAUUSD: { symbol: 'XAUUSD', name: 'Gold', digits: 2, contract: 100, day: 'ny', round: 50 },\n  BTCUSD: { symbol: 'BTCUSD', name: 'Bitcoin', digits: 2, contract: 1, day: 'utc', round: 1000 },\n};\n\n// Forex sessions in local time, Monday to Friday.\nconst SESSIONS = [\n  { id: 'sydney', name: 'Sydney', tz: 'Australia/Sydney', open: 7, close: 16 },\n  { id: 'tokyo', name: 'Tokyo', range: 'Asia', tz: 'Asia/Tokyo', open: 9, close: 18 },\n  { id: 'london', name: 'London', range: 'London', tz: 'Europe/London', open: 8, close: 17 },\n  { id: 'newyork', name: 'New York', range: 'New York', tz: 'America/New_York', open: 8, close: 17 },\n];\n\n// ------------------------------------------------------------ time zones\nconst formatters = {};\nfunction zoned(ts, tz) {\n  formatters[tz] ||= new Intl.DateTimeFormat('en-GB', {\n    timeZone: tz, hourCycle: 'h23', weekday: 'short',\n    year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', second: '2-digit',\n  });\n  const p = {};\n  for (const { type, value } of formatters[tz].formatToParts(new Date(ts * 1000))) p[type] = value;\n  return { y: +p.year, m: +p.month, d: +p.day, h: +p.hour, min: +p.minute, s: +p.second, wd: p.weekday };\n}\n\n// The UTC time of a wall-clock time in a time zone (DST-aware).\nfunction wallToUtc(tz, y, m, d, h = 0, min = 0) {\n  const wall = Date.UTC(y, m - 1, d, h, min) / 1000;\n  let ts = wall;\n  for (let i = 0; i < 3; i++) {\n    const z = zoned(ts, tz);\n    const offset = Date.UTC(z.y, z.m - 1, z.d, z.h, z.min, z.s) / 1000 - ts;\n    const next = wall - offset;\n    if (next === ts) break;\n    ts = next;\n  }\n  return ts;\n}\n\n// New York time without Intl, for loops over thousands of bars (a Worker on the free\n// plan gets 10 ms of CPU per request). US daylight saving runs from the second Sunday\n// in March, 02:00 local (07:00 UTC), to the first Sunday in November, 02:00 local (06:00 UTC).\nfunction nthSunday(y, month, n, hourUtc) {\n  const first = new Date(Date.UTC(y, month - 1, 1)).getUTCDay();\n  return Date.UTC(y, month - 1, 1 + ((7 - first) % 7) + 7 * (n - 1), hourUtc) / 1000;\n}\nconst usDst = {};\nfunction nyOffset(ts) {\n  // The year only picks the daylight-saving window, and both windows sit far from New\n  // Year, so the average Gregorian year (365.2425 days) is exact enough and needs no Date.\n  const y = 1970 + Math.floor(ts / 31556952);\n  const [from, to] = (usDst[y] ||= [nthSunday(y, 3, 2, 7), nthSunday(y, 11, 1, 6)]);\n  return ts >= from && ts < to ? -4 * 3600 : -5 * 3600;\n}\nconst DAY = 86400;\nconst nyHour = (ts) => Math.floor(((((ts + nyOffset(ts)) % DAY) + DAY) % DAY) / 3600);\n\n// A trading day as a whole number of days since 1970 (fast; dayKey gives the same day as text).\nfunction dayIndex(ts, market) {\n  if (market.day === 'utc') return Math.floor(ts / DAY);\n  const i = Math.floor((ts + nyOffset(ts) + 7 * 3600) / DAY);\n  const wd = (i + 4) % 7; // 1 January 1970 was a Thursday; 0 is Sunday\n  return wd === 6 ? i + 2 : wd === 0 ? i + 1 : i;\n}\n\nconst iso = (y, m, d) => `${y}-${String(m).padStart(2, '0')}-${String(d).padStart(2, '0')}`;\nconst addDays = (key, n) => new Date(Date.parse(key + 'T00:00:00Z') + n * 86400e3).toISOString().slice(0, 10);\nconst weekdayOf = (key) => new Date(key + 'T00:00:00Z').getUTCDay(); // 0 Sunday ... 6 Saturday\nconst mondayOf = (key) => addDays(key, -((weekdayOf(key) + 6) % 7));\n\n// The trading day a moment belongs to. Gold's day ends at 17:00 New York (as on\n// broker charts), and a weekend belongs to the Monday after it; Bitcoin uses UTC days.\nconst keyOf = (index) => new Date(index * DAY * 1000).toISOString().slice(0, 10);\nconst dayKey = (ts, market) => keyOf(dayIndex(ts, market));\n\n// ------------------------------------------------------------------- bars\n// Merge bars (or days) that share a key into one bar per key.\nfunction groupBars(bars, keyOf) {\n  const out = [];\n  for (const b of bars) {\n    const key = keyOf(b);\n    const last = out[out.length - 1];\n    if (last && last.key === key) {\n      last.h = Math.max(last.h, b.h);\n      last.l = Math.min(last.l, b.l);\n      last.c = b.c;\n    } else {\n      out.push({ key, t: b.t, o: b.o, h: b.h, l: b.l, c: b.c });\n    }\n  }\n  return out;\n}\n\nfunction toDays(bars, market) {\n  const days = [];\n  let index = null;\n  for (const b of bars) {\n    const i = dayIndex(b.t, market);\n    const last = days[days.length - 1];\n    if (last && i === index) {\n      last.h = Math.max(last.h, b.h);\n      last.l = Math.min(last.l, b.l);\n      last.c = b.c;\n    } else {\n      index = i;\n      days.push({ key: keyOf(i), t: b.t, o: b.o, h: b.h, l: b.l, c: b.c });\n    }\n  }\n  return days;\n}\n\n// Wilder's average true range over completed days.\nfunction atr(days, period = 14) {\n  if (days.length < period + 1) return null;\n  const tr = days.slice(1).map((d, i) => Math.max(d.h - d.l, Math.abs(d.h - days[i].c), Math.abs(d.l - days[i].c)));\n  let value = tr.slice(0, period).reduce((a, b) => a + b, 0) / period;\n  for (const x of tr.slice(period)) value = (value * (period - 1) + x) / period;\n  return value;\n}\n\nfunction rangeOf(bars, from, to) {\n  const inside = bars.filter((b) => b.t >= from && b.t < to);\n  if (!inside.length) return null;\n  return { high: Math.max(...inside.map((b) => b.h)), low: Math.min(...inside.map((b) => b.l)) };\n}\n\n// Session windows on a trading day's date, in UTC.\nfunction sessionWindow(session, key) {\n  const [y, m, d] = key.split('-').map(Number);\n  return { from: wallToUtc(session.tz, y, m, d, session.open), to: wallToUtc(session.tz, y, m, d, session.close) };\n}\n\n// ---------------------------------------------------------------- snapshot\n// days: daily bars (the last may be today's, still forming); intraday: 15-minute bars.\nfunction snapshot(market, days, intraday, now) {\n  const today = dayKey(now, market);\n  const done = days.filter((d) => d.key < today);\n  let current = days.find((d) => d.key === today) || null;\n  const fresh = intraday.filter((b) => dayKey(b.t, market) === today);\n  if (fresh.length) {\n    current = {\n      key: today, t: current ? current.t : fresh[0].t, o: current ? current.o : fresh[0].o,\n      h: Math.max(current ? current.h : -Infinity, ...fresh.map((b) => b.h)),\n      l: Math.min(current ? current.l : Infinity, ...fresh.map((b) => b.l)),\n      c: fresh[fresh.length - 1].c,\n    };\n  }\n  const prev = done[done.length - 1] || null;\n  const price = intraday.length ? intraday[intraday.length - 1].c : current ? current.c : prev ? prev.c : null;\n\n  const thisWeek = mondayOf(today);\n  const weeks = groupBars(done, (d) => mondayOf(d.key));\n  const prevWeek = [...weeks].reverse().find((w) => w.key < thisWeek) || null;\n  const weekOpenDay = days.find((d) => mondayOf(d.key) === thisWeek) || null;\n\n  const averageRange = atr(done);\n  const todayRange = current ? current.h - current.l : 0;\n\n  const levels = [];\n  const add = (id, name, value) => { if (Number.isFinite(value)) levels.push({ id, name, price: value }); };\n  if (prev) { add('pdh', 'Previous day high', prev.h); add('pdl', 'Previous day low', prev.l); }\n  if (prevWeek) { add('pwh', 'Previous week high', prevWeek.h); add('pwl', 'Previous week low', prevWeek.l); }\n  if (current) add('do', 'Day open', current.o);\n  if (weekOpenDay) add('wo', 'Week open', weekOpenDay.o);\n\n  const sessions = {};\n  for (const s of SESSIONS.filter((x) => x.range)) {\n    const { from, to } = sessionWindow(s, today);\n    const r = from <= now ? rangeOf(intraday, from, Math.min(to, now + 1)) : null;\n    sessions[s.id] = r && { ...r, from, to, done: now >= to };\n    if (r) { add(`${s.id}_h`, `${s.range} high`, r.high); add(`${s.id}_l`, `${s.range} low`, r.low); }\n  }\n  if (Number.isFinite(price)) {\n    const below = Math.floor(price / market.round) * market.round;\n    add('round_up', 'Round number', below + market.round);\n    add('round_down', 'Round number', below === price ? below - market.round : below);\n  }\n  levels.sort((a, b) => b.price - a.price);\n\n  return {\n    symbol: market.symbol, name: market.name, digits: market.digits, day: today,\n    price,\n    dayOpen: current ? current.o : null,\n    dayHigh: current ? current.h : null,\n    dayLow: current ? current.l : null,\n    change: current && Number.isFinite(price) ? price - current.o : null,\n    changePct: current && Number.isFinite(price) ? ((price - current.o) / current.o) * 100 : null,\n    atr: averageRange,\n    todayRange,\n    rangePct: averageRange ? (todayRange / averageRange) * 100 : null,\n    levels,\n    sessions,\n  };\n}\n\n// ------------------------------------------------------------ session clock\n// Which sessions are open at `now`, and when each next opens or closes.\nfunction sessionClock(now) {\n  return SESSIONS.map((s) => {\n    const z = zoned(now, s.tz);\n    const base = iso(z.y, z.m, z.d);\n    let open = null;\n    let next = null;\n    for (let i = -1; i <= 7 && !next; i++) {\n      const key = addDays(base, i);\n      const wd = weekdayOf(key);\n      if (wd === 0 || wd === 6) continue;\n      const w = sessionWindow(s, key);\n      if (w.from <= now && now < w.to) open = w;\n      else if (w.from > now && !next) next = w;\n    }\n    return open\n      ? { id: s.id, name: s.name, open: true, closesIn: open.to - now, until: open.to }\n      : { id: s.id, name: s.name, open: false, opensIn: next ? next.from - now : null, at: next && next.from };\n  });\n}\n\n// Gold closes from Friday 17:00 to Sunday 18:00 New York, with a daily break\n// from 17:00 to 18:00; Bitcoin never closes.\nfunction marketStatus(market, now) {\n  if (market.day === 'utc') return { open: true };\n  const z = zoned(now, 'America/New_York');\n  const key = iso(z.y, z.m, z.d);\n  const wd = weekdayOf(key);\n  const hour = z.h + z.min / 60;\n  const at = (dayOffset, h) => {\n    const [y, m, d] = addDays(key, dayOffset).split('-').map(Number);\n    return wallToUtc('America/New_York', y, m, d, h);\n  };\n  if (wd === 6) return { open: false, reason: 'weekend', opensAt: at(1, 18) };\n  if (wd === 0 && hour < 18) return { open: false, reason: 'weekend', opensAt: at(0, 18) };\n  if (wd === 5 && hour >= 17) return { open: false, reason: 'weekend', opensAt: at(2, 18) };\n  if (hour >= 17 && hour < 18) return { open: false, reason: 'daily break', opensAt: at(0, 18) };\n  const closeDay = hour >= 18 ? 1 : 0;\n  return { open: true, closesAt: at(closeDay, 17), weekendClose: weekdayOf(addDays(key, closeDay)) === 5 };\n}\n\n// ------------------------------------------------------------------- risk\n// usdPerUnit: the US-dollar value of one unit of the account currency\n// (1 for USD accounts; about 1.3 for GBP). Lots round down to the broker's step.\nfunction lotSize({ balance, riskPct, entry, stop, contract, usdPerUnit = 1, step = 0.01, min = 0.01 }) {\n  const riskMoney = (balance * riskPct) / 100;\n  const distance = Math.abs(entry - stop);\n  const riskPerLot = (distance * contract) / usdPerUnit; // account currency lost at the stop, per 1.00 lot\n  if (!(riskMoney > 0) || !(riskPerLot > 0)) return null;\n  const lots = Math.floor(riskMoney / riskPerLot / step + 1e-9) * step;\n  const rounded = Math.round(lots * 100) / 100;\n  const side = entry > stop ? 'long' : 'short';\n  const r = (k) => (side === 'long' ? entry + k * distance : entry - k * distance);\n  return {\n    side, riskMoney, distance, riskPerLot,\n    lots: rounded,\n    tooSmall: rounded < min,\n    actualRisk: rounded * riskPerLot,\n    perPoint: (rounded * contract) / usdPerUnit, // account currency per $1 move\n    targets: [1, 2, 3].map((k) => ({ r: k, price: r(k), profit: k * rounded * riskPerLot })),\n  };\n}\n\n// ------------------------------------------------------------- formatting\nconst fmtNum = (v, digits = 2) =>\n  Number.isFinite(v) ? v.toLocaleString('en-GB', { minimumFractionDigits: digits, maximumFractionDigits: digits }) : '—';\n\nfunction fmtDuration(seconds) {\n  if (!Number.isFinite(seconds)) return '—';\n  const m = Math.max(0, Math.round(seconds / 60));\n  const d = Math.floor(m / 1440);\n  const h = Math.floor((m % 1440) / 60);\n  if (d) return `${d}d ${h}h`;\n  return h ? `${h}h ${m % 60}m` : `${m % 60}m`;\n}\n\n// ------------------------------------------------------- probability engine\n// The model: over the rest of the trading day, log price moves like a trendless\n// random walk whose variance follows the market's own hour-of-day pattern (gold is\n// quiet in Asia and busy at the London and New York opens). Under that model the\n// reflection principle gives the chance of touching a level before the close.\n// calibrate() replays history out of sample to show how honest the numbers are.\n\n// Standard normal CDF (Abramowitz and Stegun 7.1.26, error below 1.5e-7).\nfunction normCdf(x) {\n  const z = Math.abs(x) / Math.SQRT2;\n  const t = 1 / (1 + 0.3275911 * z);\n  const erf = 1 - ((((1.061405429 * t - 1.453152027) * t + 1.421413741) * t - 0.284496736) * t + 0.254829592) * t * Math.exp(-z * z);\n  return x >= 0 ? (1 + erf) / 2 : (1 - erf) / 2;\n}\n\n// Variance of hourly log returns for each hour of the day (New York time), from\n// hourly bars. Thin hours are pulled towards the all-hours average.\nfunction volProfile(hourly, shrink = 5) {\n  const sums = new Array(24).fill(0);\n  const counts = new Array(24).fill(0);\n  for (let i = 1; i < hourly.length; i++) {\n    const a = hourly[i - 1];\n    const b = hourly[i];\n    if (b.t - a.t !== 3600 || !(a.c > 0) || !(b.c > 0)) continue; // skip breaks and weekends\n    const r = Math.log(b.c / a.c);\n    const h = nyHour(b.t);\n    sums[h] += r * r;\n    counts[h] += 1;\n  }\n  const n = counts.reduce((a, b) => a + b, 0);\n  const overall = n ? sums.reduce((a, b) => a + b, 0) / n : 0;\n  return sums.map((s, h) => (s + shrink * overall) / (counts[h] + shrink));\n}\n\n// Expected variance of log price between two moments, hour by hour.\nfunction varianceBetween(profile, from, to) {\n  let v = 0;\n  for (let t = from; t < to;) {\n    const next = Math.min(to, (Math.floor(t / 3600) + 1) * 3600);\n    v += (profile[nyHour(t)] * (next - t)) / 3600;\n    t = next;\n  }\n  return v;\n}\n\n// When the current trading day ends: 17:00 New York for gold, midnight UTC for Bitcoin.\nfunction dayEnd(key, market) {\n  const [y, m, d] = key.split('-').map(Number);\n  if (market.day === 'utc') return Date.UTC(y, m - 1, d + 1) / 1000;\n  const naive = Date.UTC(y, m - 1, d, 17) / 1000;\n  return naive - nyOffset(naive);\n}\n\n// Chance of touching `level` before the close, with `variance` of log price left.\nfunction touchProb(price, level, variance) {\n  if (!(price > 0) || !(level > 0)) return null;\n  if (!(variance > 0)) return price === level ? 1 : 0;\n  const z = Math.abs(Math.log(level / price)) / Math.sqrt(variance);\n  return Math.min(1, 2 * (1 - normCdf(z)));\n}\n\n// Chance of closing beyond `level`, on its side of the price.\nfunction beyondProb(price, level, variance) {\n  if (!(variance > 0)) return 0;\n  return 1 - normCdf(Math.abs(Math.log(level / price)) / Math.sqrt(variance));\n}\n\n// The band that holds the close with a given probability (k = 1: 68%, k = 2: 95%).\nconst band = (price, variance, k) => [price * Math.exp(-k * Math.sqrt(variance)), price * Math.exp(k * Math.sqrt(variance))];\n\n// The widening cone from now to the close, every `step` seconds.\nfunction cone(price, profile, from, to, step = 900) {\n  const points = [];\n  let v = 0;\n  for (let t = from; t < to;) {\n    const next = Math.min(to, (Math.floor(t / step) + 1) * step);\n    v += varianceBetween(profile, t, next);\n    t = next;\n    const [l1, u1] = band(price, v, 1);\n    const [l2, u2] = band(price, v, 2);\n    points.push({ t, l1, u1, l2, u2 });\n  }\n  return points;\n}\n\n// Probabilities for each level that can still be reached today. Levels inside\n// today's range have already been touched.\nfunction levelOdds(levels, price, high, low, variance) {\n  return levels.map((l) => {\n    const touched = Number.isFinite(high) && Number.isFinite(low) && l.price <= high && l.price >= low;\n    return { ...l, side: l.price >= price ? 'above' : 'below', touched,\n      touch: touched ? 1 : touchProb(price, l.price, variance),\n      close: beyondProb(price, l.price, variance) };\n  });\n}\n\n// Descriptive state of the market from hourly bars: trend efficiency over the last\n// 24 hours (0 = choppy, 1 = one-way), momentum in standard deviations over 1, 4 and\n// 24 hours, and where the last 24 hours' volatility ranks against the history.\nfunction marketState(hourly, profile) {\n  const n = hourly.length;\n  if (n < 50) return null;\n  const closes = hourly.map((b) => b.c);\n  const last = closes[n - 1];\n  const window = closes.slice(-25);\n  let path = 0;\n  for (let i = 1; i < window.length; i++) path += Math.abs(window[i] - window[i - 1]);\n  const efficiency = path ? Math.abs(window[window.length - 1] - window[0]) / path : 0;\n  const hourVar = profile.reduce((a, b) => a + b, 0) / 24;\n  const momentum = (h) => Math.log(last / closes[n - 1 - h]) / Math.sqrt(hourVar * h);\n  const sq = [0];\n  for (let i = 1; i < n; i++) sq.push(sq[i - 1] + Math.log(closes[i] / closes[i - 1]) ** 2);\n  const rv = (i) => sq[i] - sq[i - 24];\n  const now = rv(n - 1);\n  const past = [];\n  for (let i = 24; i < n - 24; i += 6) past.push(rv(i));\n  const rank = past.filter((x) => x < now).length / past.length;\n  return { efficiency, momentum: { h1: momentum(1), h4: momentum(4), h24: momentum(24) }, volRank: rank, vol24: Math.sqrt(now) };\n}\n\n// Out-of-sample check of the touch probabilities on the previous day's high and low.\n// For each past day: a volatility profile from the `lookback` days before it only,\n// then at every hourly bar a forecast for each level not yet touched, scored against\n// what happened by the close.\n// One pass over the bars (it runs inside the Worker's CPU budget): the profile rolls\n// forward a day at a time, and the variance left to the close is a suffix sum.\nfunction calibrate(hourly, market, lookback = 20) {\n  const days = [];\n  for (let i = 0; i < hourly.length; i++) {\n    const b = hourly[i];\n    const a = hourly[i - 1];\n    const day = dayIndex(b.t, market);\n    const r2 = a && b.t - a.t === 3600 && a.c > 0 && b.c > 0 ? Math.log(b.c / a.c) ** 2 : null;\n    const bar = { ...b, hour: nyHour(b.t), r2 };\n    const last = days[days.length - 1];\n    if (last && last.day === day) last.bars.push(bar);\n    else days.push({ day, bars: [bar] });\n  }\n  const sums = new Array(24).fill(0);\n  const counts = new Array(24).fill(0);\n  const tally = (bars, sign) => {\n    for (const b of bars) if (b.r2 !== null) { sums[b.hour] += sign * b.r2; counts[b.hour] += sign; }\n  };\n  const pairs = [];\n  for (let d = 0; d < days.length - 1; d++) {\n    if (d > lookback) {\n      const n = counts.reduce((a, b) => a + b, 0);\n      const overall = n ? sums.reduce((a, b) => a + b, 0) / n : 0;\n      const profile = sums.map((s, h) => (s + 5 * overall) / (counts[h] + 5));\n      const prev = days[d - 1].bars;\n      let pdh = -Infinity;\n      let pdl = Infinity;\n      for (const b of prev) { pdh = Math.max(pdh, b.h); pdl = Math.min(pdl, b.l); }\n      const bars = days[d].bars;\n      const k = bars.length;\n      const highAfter = new Array(k);\n      const lowAfter = new Array(k);\n      const varAfter = new Array(k);\n      for (let i = k - 1; i >= 0; i--) {\n        highAfter[i] = Math.max(bars[i].h, i + 1 < k ? highAfter[i + 1] : -Infinity);\n        lowAfter[i] = Math.min(bars[i].l, i + 1 < k ? lowAfter[i + 1] : Infinity);\n        varAfter[i] = profile[bars[i].hour] + (i + 1 < k ? varAfter[i + 1] : 0);\n      }\n      let high = -Infinity;\n      let low = Infinity;\n      for (let i = 0; i < k; i++) {\n        const price = bars[i].o;\n        if (high < pdh && price < pdh) pairs.push([touchProb(price, pdh, varAfter[i]), highAfter[i] >= pdh ? 1 : 0]);\n        if (low > pdl && price > pdl) pairs.push([touchProb(price, pdl, varAfter[i]), lowAfter[i] <= pdl ? 1 : 0]);\n        high = Math.max(high, bars[i].h);\n        low = Math.min(low, bars[i].l);\n      }\n    }\n    // Roll the profile's window forward: this day in, the day `lookback` back out.\n    tally(days[d].bars, 1);\n    if (d - lookback >= 0) tally(days[d - lookback].bars, -1);\n  }\n  if (pairs.length < 50) return null;\n  const rate = pairs.reduce((a, [, o]) => a + o, 0) / pairs.length;\n  const brier = pairs.reduce((a, [p, o]) => a + (p - o) ** 2, 0) / pairs.length;\n  const reference = rate * (1 - rate); // always forecasting the average rate\n  const bins = [];\n  for (let k = 0; k < 5; k++) {\n    const lo = k / 5;\n    const hi = (k + 1) / 5;\n    const inside = pairs.filter(([p]) => p >= lo && (k === 4 ? p <= hi : p < hi));\n    if (!inside.length) continue;\n    bins.push({ lo, hi, n: inside.length,\n      predicted: inside.reduce((a, [p]) => a + p, 0) / inside.length,\n      observed: inside.reduce((a, [, o]) => a + o, 0) / inside.length });\n  }\n  return { days: days.length - 2 - lookback, n: pairs.length, brier, skill: reference ? 1 - brier / reference : 0, bins };\n}\n\n// Baseline odds for a trade on a trendless market: the chance the target comes\n// before the stop, and the typical time until one of them is hit.\nfunction tradeOdds(entry, stop, target, hourVar) {\n  const risk = Math.abs(entry - stop);\n  const reward = Math.abs(target - entry);\n  if (!(risk > 0) || !(reward > 0)) return null;\n  const sigma2 = hourVar * entry * entry; // price variance per hour\n  return { targetFirst: risk / (risk + reward), hours: sigma2 > 0 ? (risk * reward) / sigma2 : null };\n}\n\n\n// ------------------------------------------------------------------ setup\nconst BOT = 'TCPInnerCircleBot';\nconst tg = window.Telegram && window.Telegram.WebApp;\nconst demo = new URLSearchParams(location.search).has('demo');\nconst $ = (id) => document.getElementById(id);\nconst store = {\n  get: (k) => { try { return localStorage.getItem('tcp.' + k); } catch { return null; } },\n  set: (k, v) => { try { localStorage.setItem('tcp.' + k, v); } catch {} },\n};\nfor (const el of document.querySelectorAll('[data-crown]')) el.replaceWith($('crown').content.cloneNode(true));\nif (tg) {\n  tg.ready();\n  tg.expand();\n  try { tg.setHeaderColor('#0E0D0B'); tg.setBackgroundColor('#0E0D0B'); tg.disableVerticalSwipes && tg.disableVerticalSwipes(); } catch {}\n}\nconst haptic = () => { try { tg && tg.HapticFeedback.selectionChanged(); } catch {} };\nconst clock = () => Math.floor(Date.now() / 1000);\nconst money = (v, ccy) => (ccy === 'GBP' ? '£' : ccy === 'EUR' ? '€' : '$') + fmtNum(v, 2);\nconst signed = (v, d) => (v > 0 ? '+' : v < 0 ? '−' : '') + fmtNum(Math.abs(v), d);\nconst pct = (p) => (p == null ? '—' : p >= 0.995 ? '>99%' : p < 0.005 ? '<1%' : `${Math.round(p * 100)}%`);\nconst ago = (t) => { const s = clock() - t; return s < 10 ? 'just now' : s < 90 ? `${s}s ago` : `${fmtDuration(s)} ago`; };\nconst ordinal = (n) => n + (n % 100 >= 11 && n % 100 <= 13 ? 'th' : ['th', 'st', 'nd', 'rd'][n % 10] || 'th');\nconst tzOffset = () => -new Date().getTimezoneOffset() * 60; // the chart shows the member's local time\n\n// ------------------------------------------------------------------- data\nasync function call(path) {\n  const res = await fetch(path, { headers: { authorization: 'tma ' + (tg ? tg.initData : '') } });\n  const body = await res.json().catch(() => ({}));\n  if (!res.ok) throw Object.assign(new Error(body.message || 'Something went wrong'), { code: body.error, status: res.status });\n  return body;\n}\n\n// Demo mode (?demo): two months of made-up prices, run through the same engine. No member data.\nconst demoWalk = {};\nfunction demoData(symbol) {\n  const m = MARKETS[symbol];\n  let seed = symbol === 'XAUUSD' ? 11 : 29;\n  const rand = () => ((seed = (seed * 16807) % 2147483647) / 2147483647);\n  const normal = () => Math.sqrt(-2 * Math.log(rand() + 1e-12)) * Math.cos(2 * Math.PI * rand());\n  const now = clock();\n  const quiet = symbol === 'XAUUSD' ? 0.0011 : 0.0035;\n  const hourSd = (h) => (h >= 8 && h < 12 ? quiet * 2.6 : h >= 3 && h < 8 ? quiet * 1.6 : quiet);\n  const bars = [];\n  let price = symbol === 'XAUUSD' ? 3712 : 64250;\n  for (let t = Math.floor((now - 90 * 86400) / 900) * 900; t <= now - 900; t += 900) {\n    if (m.day !== 'utc' && !marketStatus(m, t).open) continue;\n    const sd = hourSd(nyHour(t)) / 2 / Math.sqrt(3);\n    const o = price;\n    let h = o;\n    let l = o;\n    for (let k = 0; k < 3; k++) { price *= Math.exp(sd * normal()); h = Math.max(h, price); l = Math.min(l, price); }\n    bars.push({ t, o, h, l, c: price });\n  }\n  const hourly = groupBars(bars, (b) => Math.floor(b.t / 3600)).map((b) => ({ t: Math.floor(b.t / 3600) * 3600, o: b.o, h: b.h, l: b.l, c: b.c }));\n  const snap = snapshot(m, toDays(hourly, m), bars.slice(-400), now);\n  const profile = volProfile(hourly);\n  demoWalk[symbol] = { price: snap.price, sd: (t) => hourSd(nyHour(t)), normal };\n  return {\n    ...snap,\n    engine: { profile, dayEnd: dayEnd(snap.day, m), state: marketState([...hourly, { t: now, o: snap.price, h: snap.price, l: snap.price, c: snap.price }], profile), check: calibrate(hourly, m) },\n    spark: hourly.slice(-47).map((b) => b.c).concat(snap.price),\n    bars: bars.slice(-192).map((b) => [b.t, b.o, b.h, b.l, b.c]),\n    source: 'demo data', updated: now - 20, stale: false, fx: { USD: 1, GBP: 1.34, EUR: 1.17 },\n  };\n}\n\n// ------------------------------------------------------------------ state\nconst state = { symbol: store.get('symbol') === 'BTCUSD' ? 'BTCUSD' : 'XAUUSD', data: {}, fx: null, streaming: false };\nconst live = {}; // symbol -> { price, high, low, t }\nconst current = () => state.data[state.symbol];\nfunction quoteOf(symbol) {\n  const d = state.data[symbol];\n  const l = live[symbol];\n  if (!d || d.error) return null;\n  return { price: l ? l.price : d.price, high: l ? l.high : d.dayHigh, low: l ? l.low : d.dayLow };\n}\n\n// A new price from the stream (or the demo): the quote, today's range, the last candle and the odds follow it.\nfunction onTick(symbol, price, t) {\n  const d = state.data[symbol];\n  if (!d || d.error || !(price > 0)) return;\n  const m = MARKETS[symbol];\n  const l = (live[symbol] ||= { price: d.price, high: d.dayHigh ?? d.price, low: d.dayLow ?? d.price });\n  const direction = Math.sign(price - l.price);\n  l.price = price;\n  l.t = t;\n  if (dayKey(t, m) !== d.day) { loadMarket(symbol); return; }\n  l.high = Math.max(l.high, price);\n  l.low = Math.min(l.low, price);\n  const slot = Math.floor(t / 900) * 900;\n  const last = d.bars[d.bars.length - 1];\n  if (last && last[0] === slot) { last[2] = Math.max(last[2], price); last[3] = Math.min(last[3], price); last[4] = price; }\n  else if (!last || slot > last[0]) d.bars.push([slot, last ? last[4] : price, Math.max(price, last ? last[4] : price), Math.min(price, last ? last[4] : price), price]);\n  if (symbol === state.symbol) {\n    if (series) series.update(candle(d.bars[d.bars.length - 1]));\n    frame(direction);\n  }\n}\n\nlet pendingDirection = 0;\nlet framed = false;\nfunction frame(direction = 0) {\n  if (direction) pendingDirection = direction;\n  if (framed) return;\n  framed = true;\n  requestAnimationFrame(() => {\n    framed = false;\n    renderPrice(pendingDirection);\n    pendingDirection = 0;\n    renderOdds();\n  });\n}\n\n// Bitcoin streams from Coinbase tick by tick; the stream reconnects on its own.\nlet ws = null;\nlet wsTimer = null;\nlet wsRetry = 0;\nfunction streamBitcoin(on) {\n  if (demo) return;\n  clearTimeout(wsTimer);\n  if (!on) {\n    if (ws) { ws.onclose = null; ws.close(); ws = null; }\n    state.streaming = false;\n    return;\n  }\n  if (ws) return;\n  try { ws = new WebSocket('wss://ws-feed.exchange.coinbase.com'); } catch { return; }\n  ws.onopen = () => { wsRetry = 0; ws.send(JSON.stringify({ type: 'subscribe', product_ids: ['BTC-USD'], channels: ['ticker'] })); };\n  ws.onmessage = (e) => {\n    let msg;\n    try { msg = JSON.parse(e.data); } catch { return; }\n    if (msg.type !== 'ticker' || msg.product_id !== 'BTC-USD') return;\n    state.streaming = true;\n    onTick('BTCUSD', parseFloat(msg.price), Date.parse(msg.time) / 1000 || clock());\n  };\n  ws.onclose = () => {\n    ws = null;\n    state.streaming = false;\n    if (state.symbol === 'BTCUSD') wsTimer = setTimeout(() => streamBitcoin(true), Math.min(60e3, 2000 * 2 ** wsRetry++));\n  };\n  ws.onerror = () => ws && ws.close();\n}\n\n// Demo ticks: the same random walk, second by second, so previews move like the real thing.\nfunction demoTick() {\n  const w = demoWalk[state.symbol];\n  const m = MARKETS[state.symbol];\n  const now = Date.now() / 1000;\n  if (!w || !marketStatus(m, now).open) return;\n  w.price *= Math.exp(w.sd(now) * Math.sqrt(1.5 / 3600) * 2.2 * w.normal());\n  onTick(state.symbol, w.price, now);\n}\n\n// ---------------------------------------------------------------- engine strip\nfunction renderEngine(now) {\n  const d = current();\n  const m = MARKETS[state.symbol];\n  const open = marketStatus(m, now).open;\n  const el = $('engine');\n  let mode = 'live';\n  let text = 'starting…';\n  if (d && !d.error) {\n    if (demo) text = 'demo prices · ticking';\n    else if (!open) { mode = 'closed'; const s = marketStatus(m, now); text = `opens in ${fmtDuration(s.opensAt - now)}`; }\n    else if (d.stale) { mode = 'delayed'; text = `last prices ${ago(d.updated)}`; }\n    else if (state.symbol === 'BTCUSD' && state.streaming) text = 'streaming ticks';\n    else text = `synced ${ago(d.updated)}`;\n  }\n  el.className = `engine ${mode}`;\n  $('engineState').textContent = demo ? 'DEMO' : mode === 'live' ? 'LIVE' : mode === 'closed' ? 'CLOSED' : 'DELAYED';\n  $('engineSync').textContent = text;\n}\n\n// ------------------------------------------------------------------ quote\nfunction renderStatus(now) {\n  const m = MARKETS[state.symbol];\n  const s = marketStatus(m, now);\n  const pill = $('status');\n  pill.classList.toggle('open', s.open);\n  pill.lastElementChild.textContent = m.day === 'utc' ? 'Open 24/7'\n    : s.open ? `Open · ${s.weekendClose ? 'weekend' : 'break'} in ${fmtDuration(s.closesAt - now)}`\n    : `${s.reason === 'weekend' ? 'Weekend' : 'Break'} · opens in ${fmtDuration(s.opensAt - now)}`;\n}\n\nfunction renderPrice(direction = 0) {\n  const d = current();\n  const q = quoteOf(state.symbol);\n  if (!q) return;\n  const el = $('price');\n  el.textContent = fmtNum(q.price, d.digits);\n  if (direction) {\n    el.classList.remove('tick-up', 'tick-down');\n    void el.offsetWidth; // restart the flash\n    el.classList.add(direction > 0 ? 'tick-up' : 'tick-down');\n  }\n  const change = d.dayOpen != null ? q.price - d.dayOpen : null;\n  const ch = $('change');\n  ch.className = 'change ' + (change > 0 ? 'up' : change < 0 ? 'down' : '');\n  ch.textContent = change == null ? 'No trading yet today' : `${signed(change, d.digits)} (${signed((change / d.dayOpen) * 100, 2)}%) today`;\n  if (!direction || Date.now() - sparkAt > 2000) { sparkAt = Date.now(); renderSpark(d, q.price); }\n}\nlet sparkAt = 0;\n\nfunction renderSpark(d, price) {\n  const values = d.spark.slice(0, -1).concat(price);\n  const lo = Math.min(...values);\n  const hi = Math.max(...values);\n  const x = (i) => (i / (values.length - 1)) * 110 + 1;\n  const y = (v) => 44 - ((v - lo) / (hi - lo || 1)) * 40;\n  const path = values.map((v, i) => `${i ? 'L' : 'M'}${x(i).toFixed(1)} ${y(v).toFixed(1)}`).join(' ');\n  const rising = price >= values[0];\n  const color = rising ? '#35A68C' : '#E0613F';\n  $('spark').innerHTML = `<defs><linearGradient id=\"sparkFill\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\"><stop offset=\"0\" stop-color=\"${color}\" stop-opacity=\".28\"/><stop offset=\"1\" stop-color=\"${color}\" stop-opacity=\"0\"/></linearGradient></defs>` +\n    `<path d=\"${path} L111 46 L1 46 Z\" fill=\"url(#sparkFill)\"/><path d=\"${path}\" fill=\"none\" stroke=\"${color}\" stroke-width=\"1.6\" stroke-linejoin=\"round\"/>` +\n    `<circle cx=\"${x(values.length - 1)}\" cy=\"${y(price)}\" r=\"2.6\" fill=\"${color}\"><animate attributeName=\"r\" values=\"2.6;5;2.6\" dur=\"1.8s\" repeatCount=\"indefinite\"/><animate attributeName=\"opacity\" values=\"1;.5;1\" dur=\"1.8s\" repeatCount=\"indefinite\"/></circle>`;\n}\n\n// ------------------------------------------------------------------ chart\nlet chart = null;\nlet series = null;\nlet lines = [];\nlet coneLines = [];\nlet framedFor = null;\nconst candle = ([t, o, h, l, c]) => ({ time: t + tzOffset(), open: o, high: h, low: l, close: c });\n\nfunction ensureChart() {\n  if (chart || !window.LightweightCharts) return !!chart;\n  if ($('chartNote')) $('chartNote').remove();\n  chart = LightweightCharts.createChart($('chart'), {\n    autoSize: true,\n    layout: { background: { type: 'solid', color: 'transparent' }, textColor: '#A69D8C', fontFamily: 'JetBrains Mono', fontSize: 10 },\n    grid: { vertLines: { color: 'rgba(58,52,41,.35)' }, horzLines: { color: 'rgba(58,52,41,.35)' } },\n    rightPriceScale: { borderColor: '#2E2A22', scaleMargins: { top: 0.1, bottom: 0.08 } },\n    timeScale: { borderColor: '#2E2A22', timeVisible: true, secondsVisible: false, rightOffset: 2 },\n    crosshair: { mode: 1, vertLine: { color: '#6B6352', labelBackgroundColor: '#3A3429' }, horzLine: { color: '#6B6352', labelBackgroundColor: '#3A3429' } },\n  });\n  series = chart.addCandlestickSeries({ upColor: '#35A68C', downColor: '#E0613F', borderVisible: false, wickUpColor: '#35A68C', wickDownColor: '#E0613F' });\n  coneLines = [\n    ['rgba(166,157,140,.75)', 1], ['rgba(227,192,109,.9)', 2], ['rgba(227,192,109,.9)', 2], ['rgba(166,157,140,.75)', 1],\n  ].map(([color, lineStyle]) => chart.addLineSeries({ color, lineWidth: 1, lineStyle, priceLineVisible: false, lastValueVisible: false, crosshairMarkerVisible: false }));\n  return true;\n}\n\nconst LINE_STYLE = {\n  pdh: ['PDH', '#D8AD4E', 2], pdl: ['PDL', '#D8AD4E', 2], pwh: ['PWH', '#E3C06D', 0], pwl: ['PWL', '#E3C06D', 0],\n  tokyo_h: ['Asia H', '#8C7BD1', 2], tokyo_l: ['Asia L', '#8C7BD1', 2],\n};\n\nfunction renderChart(d) {\n  if (!ensureChart()) {\n    if (!window.LightweightCharts && $('chartNote')) $('chartNote').textContent = \"The chart couldn't load. Everything else is live.\";\n    return;\n  }\n  series.applyOptions({ priceFormat: { type: 'price', precision: d.digits, minMove: 1 / 10 ** d.digits } });\n  series.setData(d.bars.map(candle));\n  for (const l of lines) series.removePriceLine(l);\n  lines = d.levels.filter((l) => LINE_STYLE[l.id]).map((l) => {\n    const [title, color, lineStyle] = LINE_STYLE[l.id];\n    return series.createPriceLine({ price: l.price, color, lineWidth: 1, lineStyle, axisLabelVisible: true, title });\n  });\n  const points = renderCone(clock());\n  if (framedFor !== state.symbol) {\n    framedFor = state.symbol;\n    chart.timeScale().setVisibleLogicalRange({ from: Math.max(0, d.bars.length - 88), to: d.bars.length + Math.min(points, 40) + 1 });\n  }\n}\n\n// The 68% and 95% cones from now to the close, on the chart's 15-minute grid.\nfunction renderCone(now) {\n  const d = current();\n  if (!chart || !d || d.error) return 0;\n  const m = MARKETS[state.symbol];\n  const q = quoteOf(state.symbol);\n  const empty = () => { for (const s of coneLines) s.setData([]); return 0; };\n  if (!marketStatus(m, now).open || !d.engine) return empty();\n  const slot = Math.floor(now / 900) * 900;\n  const points = cone(q.price, d.engine.profile, now, d.engine.dayEnd).filter((p) => p.t % 900 === 0 || p.t === d.engine.dayEnd);\n  if (!points.length) return empty();\n  const off = tzOffset();\n  const apex = { time: slot + off, value: q.price };\n  ['u2', 'u1', 'l1', 'l2'].forEach((key, i) => coneLines[i].setData([apex, ...points.filter((p) => p.t > slot).map((p) => ({ time: p.t + off, value: p[key] }))]));\n  return points.length;\n}\n\n// ------------------------------------------------------------ probability\nlet levelOrder = '';\nfunction renderOdds() {\n  const d = current();\n  const q = quoteOf(state.symbol);\n  if (!d || d.error || !q || !d.engine) return;\n  const now = clock();\n  const m = MARKETS[state.symbol];\n  const open = marketStatus(m, now).open;\n  const variance = open ? varianceBetween(d.engine.profile, now, d.engine.dayEnd) : 0;\n  $('closeIn').textContent = open ? `close in ${fmtDuration(d.engine.dayEnd - now)}` : 'market closed';\n  if (variance > 0) {\n    const [l1, u1] = band(q.price, variance, 1);\n    const [l2, u2] = band(q.price, variance, 2);\n    const pair = (lo, hi) => `<small>HIGH</small>${fmtNum(hi, d.digits)}<br><small>LOW&nbsp;</small>${fmtNum(lo, d.digits)}`;\n    $('band68').innerHTML = pair(l1, u1);\n    $('band95').innerHTML = pair(l2, u2);\n  } else {\n    $('band68').textContent = $('band95').textContent = 'at the open';\n  }\n  const odds = levelOdds(d.levels, q.price, q.high, q.low, variance);\n  const inPlay = odds.filter((o) => !o.touched);\n  const touched = odds.filter((o) => o.touched);\n  const order = `${open}|` + odds.map((o) => o.id + (o.touched ? '*' : o.side === 'above' ? '+' : '-')).join();\n  if (order !== levelOrder) {\n    levelOrder = order;\n    const rows = inPlay.map((o) => `\n      <div class=\"lv ${o.side}\" data-id=\"${o.id}\">\n        <div class=\"lv-top\"><span class=\"lv-name\">${o.name}</span><b class=\"lv-price\">${fmtNum(o.price, d.digits)}</b><em class=\"lv-dist\"></em></div>\n        ${open ? '<div class=\"lv-odds\"><div class=\"lv-bar\"><i></i></div><span class=\"lv-pct\"></span></div>' : ''}\n      </div>`);\n    const at = inPlay.findIndex((o) => o.side === 'below');\n    rows.splice(at < 0 ? rows.length : at, 0, '<div class=\"lv now\"><span>Price now</span><b id=\"lvNow\"></b></div>');\n    $('levels').innerHTML = (open ? '' : '<div class=\"closed-note\">The market is closed: the odds come back at the open.</div>') + rows.join('') +\n      (touched.length ? `<div class=\"touched\"><span class=\"label\">Touched today</span>${touched.map((o) => `<span>${o.name} ${fmtNum(o.price, d.digits)}</span>`).join('')}</div>` : '');\n  }\n  for (const o of inPlay) {\n    const row = $('levels').querySelector(`[data-id=\"${o.id}\"]`);\n    if (!row) continue;\n    row.querySelector('.lv-dist').textContent = signed(o.price - q.price, d.digits);\n    if (!open) continue;\n    const width = `${Math.max(1.5, o.touch * 100)}%`;\n    requestAnimationFrame(() => { row.querySelector('.lv-bar i').style.width = width; });\n    row.querySelector('.lv-pct').textContent = pct(o.touch);\n  }\n  if ($('lvNow')) $('lvNow').textContent = fmtNum(q.price, d.digits);\n}\n\n// ---------------------------------------------------------- market state\nfunction meter(label, value, note, width) {\n  return `<div class=\"meter\"><div class=\"row\"><small>${label}</small><b>${value}</b></div>\n    <div class=\"track\"><i style=\"width:0\" data-w=\"${width}\"></i></div><div class=\"meta\" style=\"margin-top:6px\">${note}</div></div>`;\n}\nconst grow = (root) => requestAnimationFrame(() => requestAnimationFrame(() => {\n  for (const i of root.querySelectorAll('[data-w]')) { i.style.width = `${i.dataset.w}%`; if (i.dataset.l) i.style.left = `${i.dataset.l}%`; }\n}));\nfunction renderState(d) {\n  const s = d.engine && d.engine.state;\n  if (!s) { $('state').innerHTML = '<div class=\"meta\">The engine needs more history for this market.</div>'; return; }\n  const rank = Math.round(s.volRank * 100);\n  const volWord = rank < 25 ? 'Quiet' : rank < 60 ? 'Normal' : rank < 85 ? 'Active' : 'Extreme';\n  const eff = Math.round(s.efficiency * 100);\n  const trendWord = eff < 20 ? 'Choppy' : eff < 45 ? 'Two-way' : eff < 70 ? 'Trending' : 'Strong trend';\n  const mom = [['1h', s.momentum.h1], ['4h', s.momentum.h4], ['24h', s.momentum.h24]].map(([k, z]) => {\n    const c = Math.max(-3, Math.min(3, z || 0));\n    const w = (Math.abs(c) / 3) * 50;\n    return `<div class=\"mom\"><span>${k}</span><div class=\"track mid\"><i class=\"${c >= 0 ? 'pos' : 'neg'}\" style=\"left:50%;width:0\" data-l=\"${c >= 0 ? 50 : 50 - w}\" data-w=\"${w}\"></i></div><em class=\"${c > 0 ? 'up' : c < 0 ? 'down' : ''}\">${c >= 0 ? '+' : '−'}${Math.abs(z || 0).toFixed(1)}σ</em></div>`;\n  }).join('');\n  $('state').innerHTML =\n    meter('Volatility, last 24h', `${volWord} · ${ordinal(rank)} pct`, 'Ranked against the last two months.', Math.max(3, rank)) +\n    meter('Trend efficiency, last 24h', `${trendWord} · ${eff}%`, 'Net move ÷ total distance travelled.', Math.max(3, eff)) +\n    `<div class=\"meter\"><div class=\"row\"><small>Momentum</small><b style=\"font-size:12px;color:var(--stone)\">in standard deviations</b></div>${mom}</div>`;\n  grow($('state'));\n}\n\n// ------------------------------------------------------------ volatility\nfunction renderVolatility(d) {\n  $('range').textContent = d.todayRange ? fmtNum(d.todayRange, d.digits) : '—';\n  $('rangePct').textContent = d.rangePct != null && d.todayRange ? `${Math.round(d.rangePct)}%` : '—';\n  $('gaugeFill').style.width = `${Math.min(100, ((d.rangePct || 0) / 150) * 100)}%`;\n  $('atrLine').textContent = d.atr ? `An average day (ATR 14) moves ${fmtNum(d.atr, d.digits)}.` + (d.rangePct > 100 ? ' Today is already bigger than usual.' : '') : '';\n}\n\n// ------------------------------------------------------------ model check\nfunction renderCheck(d) {\n  const c = d.engine && d.engine.check;\n  if (!c) { $('check').innerHTML = '<div class=\"meta\">The model check needs about six weeks of history for this market.</div>'; return; }\n  const W = 320;\n  const H = 180;\n  const x = (p) => 34 + p * (W - 46);\n  const y = (p) => H - 26 - p * (H - 40);\n  const grid = [0, 0.5, 1].map((p) => `<line x1=\"${x(0)}\" x2=\"${x(1)}\" y1=\"${y(p)}\" y2=\"${y(p)}\" stroke=\"#2E2A22\"/><text x=\"${x(0) - 6}\" y=\"${y(p) + 3.5}\" text-anchor=\"end\" fill=\"#8A8274\" font-size=\"9\" font-family=\"JetBrains Mono\">${p * 100}%</text>`).join('');\n  const xs = [0, 0.5, 1].map((p) => `<text x=\"${x(p)}\" y=\"${H - 10}\" text-anchor=\"middle\" fill=\"#8A8274\" font-size=\"9\" font-family=\"JetBrains Mono\">${p * 100}%</text>`).join('');\n  const max = Math.max(...c.bins.map((b) => b.n));\n  const dots = c.bins.map((b) => `<circle cx=\"${x(b.predicted)}\" cy=\"${y(b.observed)}\" r=\"${4 + 7 * Math.sqrt(b.n / max)}\" fill=\"rgba(216,173,78,.22)\" stroke=\"#E3C06D\" stroke-width=\"1.4\"/>`).join('');\n  $('check').innerHTML = `\n    <svg id=\"checkChart\" viewBox=\"0 0 ${W} ${H}\" role=\"img\" aria-label=\"Forecast against outcome\">\n      ${grid}${xs}\n      <line x1=\"${x(0)}\" y1=\"${y(0)}\" x2=\"${x(1)}\" y2=\"${y(1)}\" stroke=\"#A69D8C\" stroke-dasharray=\"4 4\" stroke-width=\"1\"/>\n      <line x1=\"${x(0.02)}\" x2=\"${x(0.1)}\" y1=\"${y(0.86)}\" y2=\"${y(0.86)}\" stroke=\"#A69D8C\" stroke-dasharray=\"4 4\"/>\n      <text x=\"${x(0.12)}\" y=\"${y(0.86) + 3}\" fill=\"#A69D8C\" font-size=\"9\" font-family=\"JetBrains Mono\">honest line</text>\n      ${dots}\n      <text x=\"${x(0.5)}\" y=\"12\" text-anchor=\"middle\" fill=\"#A69D8C\" font-size=\"9\" font-family=\"JetBrains Mono\">what happened ↑ · what the engine said →</text>\n    </svg>\n    <div class=\"check-stats\">\n      <div><b>${c.n.toLocaleString('en-GB')}</b><span>forecasts</span></div>\n      <div><b>${c.days}</b><span>days replayed</span></div>\n      <div><b>${c.skill > 0 ? '+' : ''}${Math.round(c.skill * 100)}%</b><span>vs guessing</span></div>\n    </div>\n    <div class=\"fine\">Each dot groups forecasts of a touch on the previous day's high or low, made hour by hour on days the engine hadn't seen. Dots on the line mean it said 30% and it happened 30% of the time.${c.skill < 0 ? ' <span class=\"warn\">On this market the engine is currently doing worse than a flat guess, so treat its odds with extra care.</span>' : ''}</div>`;\n}\n\n// ------------------------------------------------------------ sessions\nfunction renderSessions(now) {\n  const list = sessionClock(now);\n  const codes = { sydney: 'SYD', tokyo: 'TKY', london: 'LDN', newyork: 'NY' };\n  const hours = Object.fromEntries(SESSIONS.map((s) => [s.id, s.close - s.open]));\n  $('sessions').innerHTML = list.map((s) => {\n    const progress = s.open ? 100 * (1 - s.closesIn / (hours[s.id] * 3600)) : 0;\n    return `<div class=\"session${s.open ? ' open' : ''}\">\n      <span class=\"code\">${codes[s.id]}</span>\n      <div><b>${s.name}</b><small>${s.open ? `Open · closes in ${fmtDuration(s.closesIn)}` : s.opensIn != null ? `Opens in ${fmtDuration(s.opensIn)}` : 'Closed'}</small></div>\n      <time>${new Date((s.open ? s.until : s.at) * 1000).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</time>\n      ${s.open ? `<span class=\"prog\" style=\"width:${progress.toFixed(1)}%\"></span>` : ''}\n    </div>`;\n  }).join('');\n  const open = list.filter((s) => s.open).map((s) => s.name);\n  $('overlap').hidden = open.length < 2;\n  $('overlap').textContent = open.length > 1 ? `${open.join(' and ')} overlap: usually the busiest hours.` : '';\n  $('localTime').textContent = new Date(now * 1000).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' });\n}\n\n// ------------------------------------------------------------ everything\nfunction renderMarket() {\n  const d = current();\n  const m = MARKETS[state.symbol];\n  $('quoteName').textContent = `${m.name} · ${state.symbol === 'XAUUSD' ? 'spot' : 'BTC-USD'}`;\n  const now = clock();\n  renderStatus(now);\n  renderEngine(now);\n  if (!d || d.error) {\n    const message = d ? d.message : 'Loading…';\n    $('price').textContent = '—';\n    $('change').textContent = '';\n    $('spark').innerHTML = '';\n    $('updated').innerHTML = `<span class=\"warn\">${message}</span>`;\n    if ($('chartNote')) $('chartNote').textContent = message;\n    if (series) { series.setData([]); for (const s of coneLines) s.setData([]); }\n    $('levels').innerHTML = `<div class=\"meta\">${message}</div>`;\n    levelOrder = '';\n    for (const id of ['state', 'check']) $(id).innerHTML = '';\n    return;\n  }\n  renderPrice();\n  $('updated').innerHTML = (d.stale ? '<span class=\"warn\">Showing the last prices we had · </span>' : '') + `Source: ${d.source}`;\n  renderChart(d);\n  levelOrder = '';\n  renderOdds();\n  renderState(d);\n  renderVolatility(d);\n  renderCheck(d);\n  if (!$('entry').value || $('entry').dataset.live === '1') setLiveEntry();\n}\n\nconst inflight = {};\nfunction loadMarket(symbol) {\n  inflight[symbol] ||= (async () => {\n    try {\n      const d = demo ? demoData(symbol) : await call(`/api/markets?symbol=${symbol}`);\n      state.data[symbol] = d;\n      const streamed = live[symbol];\n      if (streamed && streamed.t > d.updated && dayKey(streamed.t, MARKETS[symbol]) === d.day) {\n        live[symbol] = { ...streamed, high: Math.max(streamed.high, d.dayHigh ?? -Infinity), low: Math.min(streamed.low, d.dayLow ?? Infinity) };\n      } else delete live[symbol];\n      if (d.fx) state.fx = d.fx;\n    } catch (err) {\n      if (!state.data[symbol] || state.data[symbol].error) state.data[symbol] = { error: err.code || 'failed', message: err.message };\n    } finally {\n      delete inflight[symbol];\n    }\n    if (symbol === state.symbol) renderMarket();\n    renderRisk();\n  })();\n  return inflight[symbol];\n}\n\nfunction selectSymbol(symbol) {\n  state.symbol = symbol;\n  store.set('symbol', symbol);\n  framedFor = null;\n  for (const b of document.querySelectorAll('.segment button')) b.setAttribute('aria-pressed', String(b.dataset.symbol === symbol));\n  streamBitcoin(symbol === 'BTCUSD');\n  levelOrder = '';\n  renderMarket();\n  loadMarket(symbol);\n}\nfor (const b of document.querySelectorAll('.segment button')) b.addEventListener('click', () => { haptic(); selectSymbol(b.dataset.symbol); });\n\n// The heartbeat: clocks, countdowns and odds move every second, even between prices.\nlet beats = 0;\nfunction heartbeat() {\n  const now = clock();\n  renderEngine(now);\n  renderStatus(now);\n  renderSessions(now);\n  const left = 900 - (now % 900);\n  $('candleTimer').textContent = `next candle ${Math.floor(left / 60)}:${String(left % 60).padStart(2, '0')}`;\n  if (!$('markets').hidden) {\n    renderOdds();\n    if (++beats % 15 === 0) renderCone(now);\n  }\n}\n\n// ------------------------------------------------------------------- risk\nconst risk = { symbol: state.symbol };\nconst num = (id) => parseFloat(String($(id).value).replace(/,/g, ''));\n$('balance').value = store.get('balance') || '';\n$('currency').value = store.get('currency') || 'USD';\n$('riskPct').value = store.get('riskPct') || '1';\n\nfunction setLiveEntry() {\n  const d = state.data[risk.symbol];\n  const q = quoteOf(risk.symbol);\n  if (q && Number.isFinite(q.price)) { $('entry').value = q.price.toFixed(d.digits); $('entry').dataset.live = '1'; }\n}\nfunction selectRiskMarket(symbol) {\n  risk.symbol = symbol;\n  for (const b of document.querySelectorAll('#riskMarket button')) b.setAttribute('aria-pressed', String(b.dataset.symbol === symbol));\n  $('contract').value = store.get('contract.' + symbol) || String(MARKETS[symbol].contract);\n  $('stop').value = '';\n  setLiveEntry();\n  if (!state.data[symbol] && symbol !== state.symbol) loadMarket(symbol);\n  renderRisk();\n}\n\nfunction renderRisk() {\n  const ccy = $('currency').value;\n  const usdPerUnit = state.fx ? state.fx[ccy] : ccy === 'USD' ? 1 : null;\n  $('fxHint').hidden = ccy === 'USD';\n  $('fxHint').textContent = usdPerUnit ? `1 ${ccy} = ${fmtNum(usdPerUnit, 4)} USD (ECB rate)` : `The ${ccy} exchange rate isn't available right now, so use your USD balance.`;\n  for (const b of document.querySelectorAll('#riskChips button')) b.setAttribute('aria-pressed', String(parseFloat(b.dataset.risk) === num('riskPct')));\n  const d = state.data[risk.symbol];\n  const digits = d && d.digits != null ? d.digits : MARKETS[risk.symbol].digits;\n  const r = usdPerUnit && lotSize({ balance: num('balance'), riskPct: num('riskPct'), entry: num('entry'), stop: num('stop'), contract: num('contract'), usdPerUnit });\n  const show = !!r;\n  $('facts').hidden = !show;\n  $('targets').hidden = !show || r.tooSmall;\n  $('oddsNote').hidden = !show || r.tooSmall;\n  if (!show) {\n    $('lots').textContent = '—';\n    $('lotsLine').textContent = !usdPerUnit ? 'Switch the account to USD for now.' : 'Enter your balance, entry and stop loss.';\n    return;\n  }\n  $('lots').textContent = r.tooSmall ? '0.00' : fmtNum(r.lots, 2);\n  $('lotsLine').innerHTML = r.tooSmall\n    ? '<span class=\"warn\">Below the 0.01 minimum: this stop is too wide for this risk.</span>'\n    : `${r.side === 'long' ? 'Buy' : 'Sell'} ${risk.symbol}, risking ${money(r.actualRisk, ccy)}`;\n  $('facts').innerHTML = [\n    ['Risk budget', `${money(r.riskMoney, ccy)} (${fmtNum(num('riskPct'), 2)}%)`],\n    ['Stop distance', fmtNum(r.distance, digits)],\n    ['Each $1 price move', money(r.perPoint, ccy)],\n    ['Loss per 1.00 lot at stop', money(r.riskPerLot, ccy)],\n  ].map(([k, v]) => `<div>${k}<b>${v}</b></div>`).join('');\n  const hourVar = d && d.engine ? d.engine.profile.reduce((a, b) => a + b, 0) / 24 : 0;\n  const odds = r.targets.map((t) => tradeOdds(num('entry'), num('stop'), t.price, hourVar));\n  $('targets').tBodies[0].innerHTML = r.targets.map((t, i) => `<tr><td>${t.r}R</td><td>${fmtNum(t.price, digits)}</td><td>${pct(odds[i] && odds[i].targetFirst)}</td><td class=\"up\">+${money(t.profit, ccy)}</td></tr>`).join('');\n  const first = odds[0];\n  $('oddsNote').innerHTML = `<b>ODDS</b> are the chance the target comes before the stop if the market moves at random. A 2R trade needs to win more than <b>${pct(1 / 3)}</b> of the time to make money; beating those odds is what an edge means.` +\n    (first && first.hours ? ` At this market's usual volatility, a 1R trade like this one is typically decided in about <b>${fmtDuration(first.hours * 3600)}</b>.` : '');\n}\n\nfor (const id of ['balance', 'currency', 'riskPct', 'entry', 'stop', 'contract']) {\n  $(id).addEventListener('input', () => {\n    if (id === 'entry') $('entry').dataset.live = '0';\n    if (['balance', 'currency', 'riskPct'].includes(id)) store.set(id, $(id).value);\n    if (id === 'contract') store.set('contract.' + risk.symbol, $(id).value);\n    renderRisk();\n  });\n}\n$('currency').addEventListener('change', renderRisk);\nfor (const b of document.querySelectorAll('#riskChips button')) b.addEventListener('click', () => { $('riskPct').value = b.dataset.risk; store.set('riskPct', b.dataset.risk); haptic(); renderRisk(); });\nfor (const b of document.querySelectorAll('#riskMarket button')) b.addEventListener('click', () => { haptic(); selectRiskMarket(b.dataset.symbol); });\n$('useLive').addEventListener('click', () => { setLiveEntry(); renderRisk(); });\n\n// ------------------------------------------------------------------- tabs\nfunction showTab(tab) {\n  for (const s of document.querySelectorAll('main > section')) s.hidden = s.id !== tab;\n  for (const b of document.querySelectorAll('nav button')) {\n    if (b.dataset.tab === tab) b.setAttribute('aria-current', 'page');\n    else b.removeAttribute('aria-current');\n  }\n  if (tab === 'markets') { levelOrder = ''; renderOdds(); }\n  window.scrollTo(0, 0);\n}\nfor (const b of document.querySelectorAll('nav button')) b.addEventListener('click', () => { haptic(); showTab(b.dataset.tab); });\n\n// ------------------------------------------------------------ sign-in gate\nfunction gate(title, text, cta) {\n  $('gateTitle').textContent = title;\n  $('gateText').textContent = text;\n  const a = $('gateCta');\n  a.hidden = !cta;\n  if (cta) {\n    a.textContent = cta.label;\n    a.href = cta.href;\n    a.onclick = (e) => { if (tg && tg.openTelegramLink) { e.preventDefault(); tg.openTelegramLink(cta.href); } };\n  }\n}\n\nasync function start() {\n  if (!demo) {\n    if (!tg || !tg.initData) {\n      return gate('Open the terminal from Telegram', 'The TCP Quant Terminal opens inside Telegram, for Inner Circle members.', { label: 'OPEN IN TELEGRAM', href: `https://t.me/${BOT}` });\n    }\n    try {\n      const me = await call('/api/me');\n      $('whoName').textContent = me.user.first_name;\n      $('whoInitial').textContent = (me.user.first_name || '?').slice(0, 1).toUpperCase();\n      $('who').hidden = false;\n    } catch (err) {\n      if (err.code === 'not_member') {\n        return gate('Members only', 'The Quant Terminal is part of the TCP Inner Circle. Join, and it unlocks here.', { label: 'JOIN THE INNER CIRCLE', href: `https://t.me/${BOT}?start=terminal` });\n      }\n      return gate(\"Couldn't sign you in\", 'Close the terminal and open it again from the bot.', null);\n    }\n  } else {\n    $('whoName').textContent = 'Demo';\n    $('whoInitial').textContent = 'D';\n    $('who').hidden = false;\n  }\n  $('gate').hidden = true;\n  selectSymbol(state.symbol);\n  selectRiskMarket(state.symbol);\n  heartbeat();\n  setInterval(heartbeat, 1000);\n  setInterval(() => document.visibilityState === 'visible' && !demo && loadMarket(state.symbol), 60e3);\n  if (demo) setInterval(demoTick, 1500);\n  document.addEventListener('visibilitychange', () => {\n    if (document.visibilityState === 'visible') { loadMarket(state.symbol); streamBitcoin(state.symbol === 'BTCUSD'); }\n    else streamBitcoin(false);\n  });\n}\nstart();\n</script>\n</body>\n</html>\n";
const FONTS = {"archivo-400.woff2":"","archivo-expanded-800.woff2":"","instrument-serif-italic.woff2":"","jetbrains-mono-500.woff2":"","jetbrains-mono-600.woff2":""};

// TCP Quant Terminal: a members-only Telegram Mini App on a Cloudflare Worker (free plan).
//
// Members open it from the bot. Telegram signs who they are (the Mini App's
// initData, checked here with the bot token), and the Worker asks Telegram
// whether they're in the Inner Circle (or the team group) before sending
// any data. Nobody logs in and nothing is stored.
//
// Each market's answer carries the probability engine's inputs (see lib.js):
// the hour-by-hour volatility profile from two months of hourly bars, the time
// of today's close, the market state, and the out-of-sample model check. The
// page recomputes the odds from these every second and on every price.
//
// Settings live in the Worker's environment, never in this file:
//   BOT_TOKEN              secret: the onboarding bot's token
//   INNER_CIRCLE_CHAT_ID   members of this group get in
//   ADMIN_CHAT_ID          optional: the team group gets in too
//   TWELVE_DATA_KEY        secret: a free twelvedata.com key, for gold prices

const SIGN_IN_MAX_AGE = 24 * 3600; // Telegram's signature on a Mini App session
const MEMBER_TTL = 600; // seconds a "yes, member" answer is reused
const NON_MEMBER_TTL = 60; // so a newly approved member gets in within a minute
// Refresh rates. Gold's free allowance is 800 requests a day: 15-minute bars every
// 150 seconds (about 550 a day) plus hourly history once an hour (about 23).
const TTL = {
  XAUUSD: { recent: 150, history: 3600 },
  BTCUSD: { recent: 60, history: 3600 },
  closed: 6 * 3600, // gold's prices don't move while it's closed
  check: 6 * 3600, // the model check changes slowly
  fx: 6 * 3600,
};
const HISTORY_BARS = 1500; // hourly: about two months, for the volatility profile and the model check
const CHART_BARS = 192; // 15-minute bars: two days

const now = () => Math.floor(Date.now() / 1000);
const enc = (s) => new TextEncoder().encode(s);
const hex = (buf) => [...new Uint8Array(buf)].map((b) => b.toString(16).padStart(2, '0')).join('');

// ------------------------------------------------------------ Telegram sign-in
async function hmac(key, data) {
  const k = await crypto.subtle.importKey('raw', key, { name: 'HMAC', hash: 'SHA-256' }, false, ['sign']);
  return crypto.subtle.sign('HMAC', k, data);
}

function sameText(a, b) {
  if (a.length !== b.length) return false;
  let diff = 0;
  for (let i = 0; i < a.length; i++) diff |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return diff === 0;
}

// https://core.telegram.org/bots/webapps#validating-data-received-via-the-mini-app
async function verifyInitData(initData, botToken, at = now()) {
  if (!initData || !botToken) return null;
  const params = new URLSearchParams(initData);
  const hash = params.get('hash') || '';
  params.delete('hash');
  const check = [...params].sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0)).map(([k, v]) => `${k}=${v}`).join('\n');
  const secret = await hmac(enc('WebAppData'), enc(botToken));
  if (!sameText(hex(await hmac(secret, enc(check))), hash.toLowerCase())) return null;
  const authDate = Number(params.get('auth_date'));
  if (!(authDate > at - SIGN_IN_MAX_AGE && authDate <= at + 60)) return null;
  let user;
  try {
    user = JSON.parse(params.get('user') || 'null');
  } catch {
    return null;
  }
  return user && Number.isInteger(user.id) ? user : null;
}

async function telegram(env, method, payload) {
  const res = await fetch(`https://api.telegram.org/bot${env.BOT_TOKEN}/${method}`, {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify(payload),
  });
  // Log the method and Telegram's reason only: the request URL holds the token.
  const data = await res.json().catch(() => ({ ok: false, description: `HTTP ${res.status}` }));
  if (!data.ok) console.error(`telegram ${method} failed: ${data.description}`);
  return data;
}

const members = new Map(); // user id -> { role, until }

async function membership(env, userId, at = now()) {
  const hit = members.get(userId);
  if (hit && hit.until > at) return hit.role;
  let role = null;
  for (const [chat, name] of [[env.INNER_CIRCLE_CHAT_ID, 'member'], [env.ADMIN_CHAT_ID, 'team']]) {
    if (!chat) continue;
    const r = await telegram(env, 'getChatMember', { chat_id: chat, user_id: userId });
    const status = r.ok ? r.result.status : '';
    if (['creator', 'administrator', 'member'].includes(status) || (status === 'restricted' && r.result.is_member)) {
      role = name;
      break;
    }
  }
  members.set(userId, { role, until: at + (role ? MEMBER_TTL : NON_MEMBER_TTL) });
  return role;
}

// ----------------------------------------------------------------- market data
const cache = new Map(); // key -> { value, at }

// Serve fresh data when it's young enough; on a failed refresh, serve the last good copy marked stale.
async function cached(key, ttl, load, at = now()) {
  const hit = cache.get(key);
  if (hit && at - hit.at < ttl) return { ...hit.value, stale: false };
  try {
    const value = await load();
    cache.set(key, { value, at });
    return { ...value, stale: false };
  } catch (err) {
    console.error(`${key} failed: ${err.message}`);
    if (hit) return { ...hit.value, stale: true };
    throw err;
  }
}

async function getJson(url, headers = {}) {
  const res = await fetch(url, { headers: { 'user-agent': 'TCP-Quant-Terminal/1.0', ...headers } });
  if (!res.ok) throw new Error(`HTTP ${res.status}`);
  return res.json();
}

// Twelve Data: [{ datetime: '2026-09-23 14:00:00', open, high, low, close }], newest first.
async function twelveData(env, interval, size) {
  const url = `https://api.twelvedata.com/time_series?symbol=XAU/USD&interval=${interval}&outputsize=${size}&timezone=UTC&apikey=${encodeURIComponent(env.TWELVE_DATA_KEY)}`;
  const data = await getJson(url);
  if (data.status !== 'ok' || !Array.isArray(data.values)) throw new Error(`Twelve Data: ${data.message || 'no data'}`);
  return data.values
    .map((v) => ({ t: Date.parse(v.datetime.replace(' ', 'T') + 'Z') / 1000, o: +v.open, h: +v.high, l: +v.low, c: +v.close }))
    .sort((a, b) => a.t - b.t);
}

// Coinbase Exchange: [[time, low, high, open, close, volume]], newest first, 300 at most.
async function coinbase(granularity, start, end) {
  const range = start ? `&start=${new Date(start * 1000).toISOString()}&end=${new Date(end * 1000).toISOString()}` : '';
  const rows = await getJson(`https://api.exchange.coinbase.com/products/BTC-USD/candles?granularity=${granularity}${range}`);
  if (!Array.isArray(rows)) throw new Error('Coinbase: no data');
  return rows.map(([t, l, h, o, c]) => ({ t, o, h, l, c }));
}

const tidy = (bars) => [...new Map(bars.map((b) => [b.t, b])).values()].sort((a, b) => a.t - b.t);

// Hourly history: the volatility profile, previous days and weeks, and the model check.
async function loadHistory(env, symbol, at) {
  if (symbol === 'XAUUSD') return twelveData(env, '1h', HISTORY_BARS);
  const hour = Math.floor(at / 3600) * 3600;
  const windows = [];
  for (let end = hour + 3600; windows.length < HISTORY_BARS / 300; end -= 300 * 3600) windows.push(coinbase(3600, end - 300 * 3600, end));
  return tidy((await Promise.all(windows)).flat());
}

const loadRecent = (env, symbol) => (symbol === 'XAUUSD' ? twelveData(env, '15min', 200) : coinbase(900).then(tidy));

async function loadMarket(env, symbol, at) {
  const market = MARKETS[symbol];
  const open = marketStatus(market, at).open;
  const ttl = TTL[symbol];
  const [history, recent] = await Promise.all([
    cached(`${symbol}:1h`, open ? ttl.history : TTL.closed, async () => {
      const bars = await loadHistory(env, symbol, at);
      return { bars, profile: volProfile(bars) };
    }, at),
    cached(`${symbol}:15m`, open ? ttl.recent : TTL.closed, async () => ({ bars: await loadRecent(env, symbol) }), at),
  ]);
  const check = await cached(`${symbol}:check`, TTL.check, async () => ({ result: calibrate(history.bars, market) }), at).catch(() => ({ result: null }));
  const snap = snapshot(market, toDays(history.bars, market), recent.bars, at);
  const live = { t: at, o: snap.price, h: snap.price, l: snap.price, c: snap.price };
  return {
    ...snap,
    engine: {
      profile: history.profile,
      dayEnd: dayEnd(snap.day, market),
      state: marketState([...history.bars, live], history.profile),
      check: check.result,
    },
    spark: history.bars.slice(-47).map((b) => b.c).concat(snap.price),
    bars: recent.bars.slice(-CHART_BARS).map((b) => [b.t, b.o, b.h, b.l, b.c]),
    source: symbol === 'XAUUSD' ? 'Twelve Data (XAU/USD spot)' : 'Coinbase (BTC-USD)',
    updated: at,
    stale: history.stale || recent.stale,
  };
}

// USD per unit of account currency, for GBP and EUR accounts (ECB rates).
async function loadFx() {
  const data = await getJson('https://api.frankfurter.app/latest?from=USD&to=GBP,EUR');
  const rates = data.rates || {};
  if (!(rates.GBP > 0 && rates.EUR > 0)) throw new Error('FX: no rates');
  return { usdPerUnit: { USD: 1, GBP: 1 / rates.GBP, EUR: 1 / rates.EUR }, date: data.date };
}

// ------------------------------------------------------------------- routes
const json = (body, status = 200) =>
  new Response(JSON.stringify(body), { status, headers: { 'content-type': 'application/json', 'cache-control': 'no-store' } });

const SECURITY = {
  'content-security-policy':
    "default-src 'self'; script-src 'self' 'unsafe-inline' https://telegram.org https://cdn.jsdelivr.net; " +
    "style-src 'self' 'unsafe-inline'; font-src 'self'; img-src 'self' data:; connect-src 'self' wss://ws-feed.exchange.coinbase.com",
  'x-content-type-options': 'nosniff',
  'referrer-policy': 'no-referrer',
};

async function api(request, env, path, url) {
  const initData = (request.headers.get('authorization') || '').replace(/^tma /, '');
  const user = await verifyInitData(initData, env.BOT_TOKEN);
  if (!user) return json({ error: 'signed_out', message: 'Open the terminal from Telegram.' }, 401);
  const role = await membership(env, user.id);
  if (!role) return json({ error: 'not_member', message: 'The Quant Terminal is for TCP Inner Circle members.' }, 403);

  if (path === '/api/me') return json({ user: { id: user.id, first_name: user.first_name || '', username: user.username || '' }, role });

  if (path === '/api/markets') {
    const symbol = url.searchParams.get('symbol');
    if (!MARKETS[symbol]) return json({ error: 'unknown_symbol' }, 400);
    if (symbol === 'XAUUSD' && !env.TWELVE_DATA_KEY) {
      return json({ error: 'no_key', message: 'Gold prices need a free Twelve Data key: see terminal/SETUP.md.' }, 503);
    }
    const at = now();
    try {
      const [market, fx] = await Promise.all([
        loadMarket(env, symbol, at),
        cached('fx', TTL.fx, loadFx, at).catch(() => null),
      ]);
      return json({ ...market, fx: fx && fx.usdPerUnit });
    } catch {
      return json({ error: 'unavailable', message: 'Prices are unavailable right now. Try again in a minute.' }, 503);
    }
  }
  return json({ error: 'not_found' }, 404);
}

export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    const path = url.pathname;
    if (path.startsWith('/api/')) return api(request, env, path, url);
    if (path.startsWith('/fonts/') && FONTS[path.slice(7)]) {
      const bytes = Uint8Array.from(atob(FONTS[path.slice(7)]), (c) => c.charCodeAt(0));
      return new Response(bytes, { headers: { 'content-type': 'font/woff2', 'cache-control': 'public, max-age=31536000, immutable' } });
    }
    if (path === '/' || path === '/index.html') {
      return new Response(PAGE, { headers: { 'content-type': 'text/html; charset=utf-8', 'cache-control': 'no-cache', ...SECURITY } });
    }
    return new Response('Not found', { status: 404 });
  },
};

// For tests: forget cached answers between cases.
function resetCaches() {
  members.clear();
  cache.clear();
}
